*

\******************************************************************************/



static void cmdinfo()

{

	fprintf(stderr, "Image Information Utility (Version %s).\n",

	  JAS_VERSION);

	fprintf(stderr,

	  "Copyright (c) 2001 Michael David Adams.\n"

	  "All rights reserved.\n"

	  );

}



static void usage()

{

	cmdinfo();

	fprintf(stderr, "usage:\n");

	fprintf(stderr,"%s ", cmdname);

	fprintf(stderr, "[-f image_file]\n");

	exit(EXIT_FAILURE);

}

