    r = aug_set(aug, "/files/etc/yum.repos.d/new.repo/newrepo/baseurl",

                "http://foo.com/");

    CuAssertIntEquals(tc, 0, r);



    r = aug_save(aug);

    CuAssertIntEquals(tc, 0, r);



    r = aug_match(aug, "/augeas/files/etc/yum.repos.d/new.repo/path", NULL);

    CuAssertIntEquals(tc, 1, r);

}



