	},

	[UWB_RC_EVT_BPOIE_CHANGE] = {

		.handler = uwbd_evt_handle_rc_bpoie_change,

		.name = "BPOIE_CHANGE"

	},

	[UWB_RC_EVT_BP_SLOT_CHANGE] = {

		.handler = uwbd_evt_handle_rc_bp_slot_change,

