 *	IPV6 GSO/GRO offload support

 *	Linux INET6 implementation

 *

 *	This program is free software; you can redistribute it and/or

 *      modify it under the terms of the GNU General Public License

 *      as published by the Free Software Foundation; either version

 *      2 of the License, or (at your option) any later version.

 *

 *      UDPv6 GSO support

 */

#include <linux/skbuff.h>

#include <net/protocol.h>

#include <net/ipv6.h>

#include <net/udp.h>

#include <net/ip6_checksum.h>

#include "ip6_offload.h"



static int udp6_ufo_send_check(struct sk_buff *skb)

{

	const struct ipv6hdr *ipv6h;

	struct udphdr *uh;



	if (!pskb_may_pull(skb, sizeof(*uh)))

		return -EINVAL;



	if (likely(!skb->encapsulation)) {

		ipv6h = ipv6_hdr(skb);

		uh = udp_hdr(skb);



		uh->check = ~csum_ipv6_magic(&ipv6h->saddr, &ipv6h->daddr, skb->len,

					     IPPROTO_UDP, 0);

		skb->csum_start = skb_transport_header(skb) - skb->head;

		skb->csum_offset = offsetof(struct udphdr, check);

		skb->ip_summed = CHECKSUM_PARTIAL;

	}



	return 0;

}



static struct sk_buff *udp6_ufo_fragment(struct sk_buff *skb,

					 netdev_features_t features)

{

	struct sk_buff *segs = ERR_PTR(-EINVAL);

	unsigned int mss;

	unsigned int unfrag_ip6hlen, unfrag_len;

	struct frag_hdr *fptr;

	u8 *packet_start, *prevhdr;

	u8 nexthdr;

	u8 frag_hdr_sz = sizeof(struct frag_hdr);

	int offset;

	__wsum csum;

	int tnl_hlen;



	mss = skb_shinfo(skb)->gso_size;

	if (unlikely(skb->len <= mss))

		goto out;



	if (skb_gso_ok(skb, features | NETIF_F_GSO_ROBUST)) {

		/* Packet is from an untrusted source, reset gso_segs. */

		int type = skb_shinfo(skb)->gso_type;



		if (unlikely(type & ~(SKB_GSO_UDP |

				      SKB_GSO_DODGY |

				      SKB_GSO_UDP_TUNNEL |

				      SKB_GSO_GRE |

				      SKB_GSO_IPIP |

				      SKB_GSO_SIT |

				      SKB_GSO_MPLS) ||

			     !(type & (SKB_GSO_UDP))))

			goto out;



		skb_shinfo(skb)->gso_segs = DIV_ROUND_UP(skb->len, mss);



		segs = NULL;

		goto out;

	}



	if (skb->encapsulation && skb_shinfo(skb)->gso_type & SKB_GSO_UDP_TUNNEL)

		segs = skb_udp_tunnel_segment(skb, features);

	else {

		/* Do software UFO. Complete and fill in the UDP checksum as HW cannot

		 * do checksum of UDP packets sent as multiple IP fragments.

		 */

		offset = skb_checksum_start_offset(skb);

		csum = skb_checksum(skb, offset, skb->len - offset, 0);

		offset += skb->csum_offset;

		*(__sum16 *)(skb->data + offset) = csum_fold(csum);

		skb->ip_summed = CHECKSUM_NONE;



		/* Check if there is enough headroom to insert fragment header. */

		tnl_hlen = skb_tnl_header_len(skb);

		if (skb_headroom(skb) < (tnl_hlen + frag_hdr_sz)) {

			if (gso_pskb_expand_head(skb, tnl_hlen + frag_hdr_sz))

				goto out;

		}



		/* Find the unfragmentable header and shift it left by frag_hdr_sz

		 * bytes to insert fragment header.

		 */

		unfrag_ip6hlen = ip6_find_1stfragopt(skb, &prevhdr);

		nexthdr = *prevhdr;

		*prevhdr = NEXTHDR_FRAGMENT;

		unfrag_len = (skb_network_header(skb) - skb_mac_header(skb)) +

			     unfrag_ip6hlen + tnl_hlen;

		packet_start = (u8 *) skb->head + SKB_GSO_CB(skb)->mac_offset;

		memmove(packet_start-frag_hdr_sz, packet_start, unfrag_len);



		SKB_GSO_CB(skb)->mac_offset -= frag_hdr_sz;

		skb->mac_header -= frag_hdr_sz;

		skb->network_header -= frag_hdr_sz;



		fptr = (struct frag_hdr *)(skb_network_header(skb) + unfrag_ip6hlen);

		fptr->nexthdr = nexthdr;

		fptr->reserved = 0;

		ipv6_select_ident(fptr, (struct rt6_info *)skb_dst(skb));



		/* Fragment the skb. ipv6 header and the remaining fields of the

		 * fragment header are updated in ipv6_gso_segment()

		 */

		segs = skb_segment(skb, features);

	}



out:

	return segs;

}

static const struct net_offload udpv6_offload = {

	.callbacks = {

		.gso_send_check =	udp6_ufo_send_check,

		.gso_segment	=	udp6_ufo_fragment,

	},

};



int __init udp_offload_init(void)

{

	return inet6_add_offload(&udpv6_offload, IPPROTO_UDP);

}

#include <xml_schema.h>



static void dealloc(xmlSchemaPtr schema)

{

  NOKOGIRI_DEBUG_START(schema);

  xmlSchemaFree(schema);

  NOKOGIRI_DEBUG_END(schema);

}



/*

 * call-seq:

 *  validate_document(document)

 *

 * Validate a Nokogiri::XML::Document against this Schema.

 */

static VALUE validate_document(VALUE self, VALUE document)

{

  xmlDocPtr doc;

  xmlSchemaPtr schema;

  xmlSchemaValidCtxtPtr valid_ctxt;

  VALUE errors;



  Data_Get_Struct(self, xmlSchema, schema);

  Data_Get_Struct(document, xmlDoc, doc);



  errors = rb_ary_new();



  valid_ctxt = xmlSchemaNewValidCtxt(schema);



  if(NULL == valid_ctxt) {

    /* we have a problem */

    rb_raise(rb_eRuntimeError, "Could not create a validation context");

  }



#ifdef HAVE_XMLSCHEMASETVALIDSTRUCTUREDERRORS

  xmlSchemaSetValidStructuredErrors(

    valid_ctxt,

    Nokogiri_error_array_pusher,

    (void *)errors

  );

#endif



  xmlSchemaValidateDoc(valid_ctxt, doc);



  xmlSchemaFreeValidCtxt(valid_ctxt);



  return errors;

}



/*

 * call-seq:

 *  validate_file(filename)

 *

 * Validate a file against this Schema.

 */

static VALUE validate_file(VALUE self, VALUE rb_filename)

{

  xmlSchemaPtr schema;

  xmlSchemaValidCtxtPtr valid_ctxt;

  const char *filename ;

  VALUE errors;



  Data_Get_Struct(self, xmlSchema, schema);

  filename = (const char*)StringValueCStr(rb_filename) ;



  errors = rb_ary_new();



  valid_ctxt = xmlSchemaNewValidCtxt(schema);



  if(NULL == valid_ctxt) {

    /* we have a problem */

    rb_raise(rb_eRuntimeError, "Could not create a validation context");

  }



#ifdef HAVE_XMLSCHEMASETVALIDSTRUCTUREDERRORS

  xmlSchemaSetValidStructuredErrors(

    valid_ctxt,

    Nokogiri_error_array_pusher,

    (void *)errors

  );

#endif



  xmlSchemaValidateFile(valid_ctxt, filename, 0);



  xmlSchemaFreeValidCtxt(valid_ctxt);



  return errors;

}



/*

 * call-seq:

 *  read_memory(string)

 *

 * Create a new Schema from the contents of +string+

 */

static VALUE read_memory(int argc, VALUE *argv, VALUE klass)

{

  VALUE content;

  VALUE parse_options;

  int parse_options_int;

  xmlSchemaParserCtxtPtr ctx;

  xmlSchemaPtr schema;

  VALUE errors;

  VALUE rb_schema;

  int scanned_args = 0;



  scanned_args = rb_scan_args(argc, argv, "11", &content, &parse_options);

  if (scanned_args == 1) {

    parse_options = rb_const_get(rb_const_get(mNokogiriXml, rb_intern("ParseOptions")), rb_intern("DEFAULT_SCHEMA"));

  }

  parse_options_int = (int)NUM2INT(rb_funcall(parse_options, rb_intern("to_i"), 0));



  ctx = xmlSchemaNewMemParserCtxt((const char *)StringValuePtr(content), (int)RSTRING_LEN(content));



  errors = rb_ary_new();

  xmlSetStructuredErrorFunc((void *)errors, Nokogiri_error_array_pusher);



#ifdef HAVE_XMLSCHEMASETPARSERSTRUCTUREDERRORS

  xmlSchemaSetParserStructuredErrors(

    ctx,

    Nokogiri_error_array_pusher,

    (void *)errors

    );

#endif



   schema = xmlSchemaParse(ctx);



  xmlSetStructuredErrorFunc(NULL, NULL);

  xmlSchemaFreeParserCtxt(ctx);



  if(NULL == schema) {

    xmlErrorPtr error = xmlGetLastError();

    if(error)

      Nokogiri_error_raise(NULL, error);

    else

      rb_raise(rb_eRuntimeError, "Could not parse document");



    return Qnil;

  }



  rb_schema = Data_Wrap_Struct(klass, 0, dealloc, schema);

  rb_iv_set(rb_schema, "@errors", errors);

  rb_iv_set(rb_schema, "@parse_options", parse_options);



  return rb_schema;

}



/* Schema creation will remove and deallocate "blank" nodes.

 * If those blank nodes have been exposed to Ruby, they could get freed

 * out from under the VALUE pointer.  This function checks to see if any of

 * those nodes have been exposed to Ruby, and if so we should raise an exception.

 */

static int has_blank_nodes_p(VALUE cache)

{

    long i;



    if (NIL_P(cache)) {

        return 0;

    }



    for (i = 0; i < RARRAY_LEN(cache); i++) {

        xmlNodePtr node;

        VALUE element = rb_ary_entry(cache, i);

        Data_Get_Struct(element, xmlNode, node);

        if (xmlIsBlankNode(node)) {

            return 1;

        }

    }



    return 0;

}



/*

 * call-seq:

 *  from_document(doc)

 *

 * Create a new Schema from the Nokogiri::XML::Document +doc+

 */

static VALUE from_document(int argc, VALUE *argv, VALUE klass)

{

  VALUE document;

  VALUE parse_options;

  int parse_options_int;

  xmlDocPtr doc;

  xmlSchemaParserCtxtPtr ctx;

  xmlSchemaPtr schema;

  VALUE errors;

  VALUE rb_schema;

  int scanned_args = 0;



  scanned_args = rb_scan_args(argc, argv, "11", &document, &parse_options);



  Data_Get_Struct(document, xmlDoc, doc);

  doc = doc->doc; /* In case someone passes us a node. ugh. */



  if (scanned_args == 1) {

    parse_options = rb_const_get(rb_const_get(mNokogiriXml, rb_intern("ParseOptions")), rb_intern("DEFAULT_SCHEMA"));

  }

  parse_options_int = (int)NUM2INT(rb_funcall(parse_options, rb_intern("to_i"), 0));



  if (has_blank_nodes_p(DOC_NODE_CACHE(doc))) {

    rb_raise(rb_eArgError, "Creating a schema from a document that has blank nodes exposed to Ruby is dangerous");

  }



  ctx = xmlSchemaNewDocParserCtxt(doc);



  errors = rb_ary_new();

  xmlSetStructuredErrorFunc((void *)errors, Nokogiri_error_array_pusher);



#ifdef HAVE_XMLSCHEMASETPARSERSTRUCTUREDERRORS

  xmlSchemaSetParserStructuredErrors(

    ctx,

    Nokogiri_error_array_pusher,

    (void *)errors

  );

#endif



  schema = xmlSchemaParse(ctx);



  xmlSetStructuredErrorFunc(NULL, NULL);

  xmlSchemaFreeParserCtxt(ctx);



  if(NULL == schema) {

    xmlErrorPtr error = xmlGetLastError();

    if(error)

      Nokogiri_error_raise(NULL, error);

    else

      rb_raise(rb_eRuntimeError, "Could not parse document");



    return Qnil;

  }



  rb_schema = Data_Wrap_Struct(klass, 0, dealloc, schema);

  rb_iv_set(rb_schema, "@errors", errors);

  rb_iv_set(rb_schema, "@parse_options", parse_options);



  return rb_schema;



  return Qnil;

}



VALUE cNokogiriXmlSchema;

void init_xml_schema()

{

  VALUE nokogiri = rb_define_module("Nokogiri");

  VALUE xml = rb_define_module_under(nokogiri, "XML");

  VALUE klass = rb_define_class_under(xml, "Schema", rb_cObject);



  cNokogiriXmlSchema = klass;



  rb_define_singleton_method(klass, "read_memory", read_memory, -1);

  rb_define_singleton_method(klass, "from_document", from_document, -1);



  rb_define_private_method(klass, "validate_document", validate_document, 1);

  rb_define_private_method(klass, "validate_file",     validate_file, 1);

}

