int mkdir_p(const char *path, mode_t mode)

{

	char *p, *dir;

	int rc = 0;



	if (!path || !*path)

		return -EINVAL;



	dir = p = strdup(path);

	if (!dir)

		return -ENOMEM;



	if (*p == '/')

		p++;



	while (p && *p) {

		char *e = strchr(p, '/');

		if (e)

			*e = '\0';

		if (*p) {

			rc = mkdir(dir, mode);

			if (rc && errno != EEXIST)

				break;

			rc = 0;

		}

		if (!e)

			break;

		*e = '/';

		p = e + 1;

	}



	free(dir);

	return rc;

}



/* returns basename and keeps dirname in the @path, if @path is "/" (root)

 * then returns empty string */

char *stripoff_last_component(char *path)

{

	char *p = path ? strrchr(path, '/') : NULL;



	if (!p)

		return NULL;

	*p = '\0';

	return p + 1;

}

