	rewind(c.script);

	ff_VerboseCheck();

	c.lineno = 1;

	while ( !c.returned && !c.broken && ff_NextToken(&c)!=tt_eof ) {

	    ff_backuptok(&c);

	    ff_statement(&c);

	}

	fclose(c.script);

	sd->done = true;

    }

    running_script = false;

}

