#define pr_fmt(fmt) KBUILD_MODNAME ": %s: " fmt, __func__



#include <net/tcp_states.h>

#include <linux/nfc.h>

#include <linux/export.h>



#include "nfc.h"



static struct nfc_sock_list raw_sk_list = {

	.lock = __RW_LOCK_UNLOCKED(raw_sk_list.lock)

};



static void nfc_sock_link(struct nfc_sock_list *l, struct sock *sk)

{

	write_lock(&l->lock);

	sk_add_node(sk, &l->head);

	write_unlock(&l->lock);

}



static void nfc_sock_unlink(struct nfc_sock_list *l, struct sock *sk)

{

	write_lock(&l->lock);

	sk_del_node_init(sk);

	write_unlock(&l->lock);

}



static void rawsock_write_queue_purge(struct sock *sk)

{

	pr_debug("sk=%p\n", sk);



	spin_lock_bh(&sk->sk_write_queue.lock);

	__skb_queue_purge(&sk->sk_write_queue);

	nfc_rawsock(sk)->tx_work_scheduled = false;

	spin_unlock_bh(&sk->sk_write_queue.lock);

}



static void rawsock_report_error(struct sock *sk, int err)

{

	pr_debug("sk=%p err=%d\n", sk, err);



	sk->sk_shutdown = SHUTDOWN_MASK;

	sk->sk_err = -err;

	sk->sk_error_report(sk);



	rawsock_write_queue_purge(sk);

}



static int rawsock_release(struct socket *sock)

{

	struct sock *sk = sock->sk;



	pr_debug("sock=%p sk=%p\n", sock, sk);



	if (!sk)

		return 0;



	if (sock->type == SOCK_RAW)

		nfc_sock_unlink(&raw_sk_list, sk);



	sock_orphan(sk);

	sock_put(sk);



	return 0;

}



static int rawsock_connect(struct socket *sock, struct sockaddr *_addr,

			   int len, int flags)

{

	struct sock *sk = sock->sk;

	struct sockaddr_nfc *addr = (struct sockaddr_nfc *)_addr;

	struct nfc_dev *dev;

	int rc = 0;



	pr_debug("sock=%p sk=%p flags=%d\n", sock, sk, flags);



	if (!addr || len < sizeof(struct sockaddr_nfc) ||

	    addr->sa_family != AF_NFC)

		return -EINVAL;



	pr_debug("addr dev_idx=%u target_idx=%u protocol=%u\n",

		 addr->dev_idx, addr->target_idx, addr->nfc_protocol);



	lock_sock(sk);



	if (sock->state == SS_CONNECTED) {

		rc = -EISCONN;

		goto error;

	}



	dev = nfc_get_device(addr->dev_idx);

	if (!dev) {

		rc = -ENODEV;

		goto error;

	}



	if (addr->target_idx > dev->target_next_idx - 1 ||

	    addr->target_idx < dev->target_next_idx - dev->n_targets) {

		rc = -EINVAL;

		goto error;

	}



	rc = nfc_activate_target(dev, addr->target_idx, addr->nfc_protocol);

	if (rc)

		goto put_dev;



	nfc_rawsock(sk)->dev = dev;

	nfc_rawsock(sk)->target_idx = addr->target_idx;

	sock->state = SS_CONNECTED;

	sk->sk_state = TCP_ESTABLISHED;

	sk->sk_state_change(sk);



	release_sock(sk);

	return 0;



put_dev:

	nfc_put_device(dev);

error:

	release_sock(sk);

	return rc;

}



static int rawsock_add_header(struct sk_buff *skb)

{

	*(u8 *)skb_push(skb, NFC_HEADER_SIZE) = 0;



	return 0;

}



static void rawsock_data_exchange_complete(void *context, struct sk_buff *skb,

					   int err)

{

	struct sock *sk = (struct sock *) context;



	BUG_ON(in_irq());



	pr_debug("sk=%p err=%d\n", sk, err);



	if (err)

		goto error;



	err = rawsock_add_header(skb);

	if (err)

		goto error_skb;



	err = sock_queue_rcv_skb(sk, skb);

	if (err)

		goto error_skb;



	spin_lock_bh(&sk->sk_write_queue.lock);

	if (!skb_queue_empty(&sk->sk_write_queue))

		schedule_work(&nfc_rawsock(sk)->tx_work);

	else

		nfc_rawsock(sk)->tx_work_scheduled = false;

	spin_unlock_bh(&sk->sk_write_queue.lock);



	sock_put(sk);

	return;



error_skb:

	kfree_skb(skb);



error:

	rawsock_report_error(sk, err);

	sock_put(sk);

}



static void rawsock_tx_work(struct work_struct *work)

{

	struct sock *sk = to_rawsock_sk(work);

	struct nfc_dev *dev = nfc_rawsock(sk)->dev;

	u32 target_idx = nfc_rawsock(sk)->target_idx;

	struct sk_buff *skb;

	int rc;



	pr_debug("sk=%p target_idx=%u\n", sk, target_idx);



	if (sk->sk_shutdown & SEND_SHUTDOWN) {

		rawsock_write_queue_purge(sk);

		return;

	}



	skb = skb_dequeue(&sk->sk_write_queue);



	sock_hold(sk);

	rc = nfc_data_exchange(dev, target_idx, skb,

			       rawsock_data_exchange_complete, sk);

	if (rc) {

		rawsock_report_error(sk, rc);

		sock_put(sk);

	}

}



static int rawsock_sendmsg(struct socket *sock, struct msghdr *msg, size_t len)

{

	struct sock *sk = sock->sk;

	struct nfc_dev *dev = nfc_rawsock(sk)->dev;

	struct sk_buff *skb;

	int rc;



	pr_debug("sock=%p sk=%p len=%zu\n", sock, sk, len);



	if (msg->msg_namelen)

		return -EOPNOTSUPP;



	if (sock->state != SS_CONNECTED)

		return -ENOTCONN;



	skb = nfc_alloc_send_skb(dev, sk, msg->msg_flags, len, &rc);

	if (skb == NULL)

		return rc;



	rc = memcpy_from_msg(skb_put(skb, len), msg, len);

	if (rc < 0) {

		kfree_skb(skb);

		return rc;

	}



	spin_lock_bh(&sk->sk_write_queue.lock);

	__skb_queue_tail(&sk->sk_write_queue, skb);

	if (!nfc_rawsock(sk)->tx_work_scheduled) {

		schedule_work(&nfc_rawsock(sk)->tx_work);

		nfc_rawsock(sk)->tx_work_scheduled = true;

	}

	spin_unlock_bh(&sk->sk_write_queue.lock);



	return len;

}



static int rawsock_recvmsg(struct socket *sock, struct msghdr *msg, size_t len,

			   int flags)

{

	int noblock = flags & MSG_DONTWAIT;

	struct sock *sk = sock->sk;

	struct sk_buff *skb;

	int copied;

	int rc;



	pr_debug("sock=%p sk=%p len=%zu flags=%d\n", sock, sk, len, flags);



	skb = skb_recv_datagram(sk, flags, noblock, &rc);

	if (!skb)

		return rc;



	copied = skb->len;

	if (len < copied) {

		msg->msg_flags |= MSG_TRUNC;

		copied = len;

	}



	rc = skb_copy_datagram_msg(skb, 0, msg, copied);



	skb_free_datagram(sk, skb);



	return rc ? : copied;

}



