void machine_restart(char *cmd)

{

	machine_shutdown();



	arm_pm_restart(reboot_mode, cmd);



	/* Give a grace period for failure to restart of 1s */

	mdelay(1000);



	/* Whoops - the platform was unable to reboot. Tell the user! */

	printk("Reboot failed -- System halted\n");

	local_irq_disable();

	while (1);

}



