		processor_modes[processor_mode(regs)],

		isa_modes[isa_mode(regs)],

		get_fs() == get_ds() ? "kernel" : "user");

#ifdef CONFIG_CPU_CP15

	{

		unsigned int ctrl;



		buf[0] = '\0';

