{

	char *end;



	if (!name || !value || !cp)

		return -BLKID_ERR_PARAM;



	*name = strip_line(*cp);



	if ((*name)[0] != '<' || (*name)[1] == '/')

		return 0;



	FIXME: finish this.

}

