/*

 * bus definition

 */

static int snd_seq_bus_match(struct device *dev, struct device_driver *drv)

{

	struct snd_seq_device *sdev = to_seq_dev(dev);

	struct snd_seq_driver *sdrv = to_seq_drv(drv);



	return strcmp(sdrv->id, sdev->id) == 0 &&

		sdrv->argsize == sdev->argsize;

}



static struct bus_type snd_seq_bus_type = {

	.name = "snd_seq",

	.match = snd_seq_bus_match,

};



/*

 * proc interface -- just for compatibility

 */

#ifdef CONFIG_SND_PROC_FS

static struct snd_info_entry *info_entry;



static int print_dev_info(struct device *dev, void *data)

{

	struct snd_seq_device *sdev = to_seq_dev(dev);

	struct snd_info_buffer *buffer = data;



	snd_iprintf(buffer, "snd-%s,%s,%d\n", sdev->id,

		    dev->driver ? "loaded" : "empty",

		    dev->driver ? 1 : 0);

	return 0;

}



static void snd_seq_device_info(struct snd_info_entry *entry,

				struct snd_info_buffer *buffer)

{

	bus_for_each_dev(&snd_seq_bus_type, NULL, buffer, print_dev_info);

}

#endif



/*

 * load all registered drivers (called from seq_clientmgr.c)

 */



#ifdef CONFIG_MODULES

/* flag to block auto-loading */

static atomic_t snd_seq_in_init = ATOMIC_INIT(1); /* blocked as default */



static int request_seq_drv(struct device *dev, void *data)

{

	struct snd_seq_device *sdev = to_seq_dev(dev);



	if (!dev->driver)

		request_module("snd-%s", sdev->id);

	return 0;

}



static void autoload_drivers(struct work_struct *work)

{

	/* avoid reentrance */

	if (atomic_inc_return(&snd_seq_in_init) == 1)

		bus_for_each_dev(&snd_seq_bus_type, NULL, NULL,

				 request_seq_drv);

	atomic_dec(&snd_seq_in_init);

}



static DECLARE_WORK(autoload_work, autoload_drivers);



static void queue_autoload_drivers(void)

{

	schedule_work(&autoload_work);

}



void snd_seq_autoload_init(void)

{

	atomic_dec(&snd_seq_in_init);

#ifdef CONFIG_SND_SEQUENCER_MODULE

	/* initial autoload only when snd-seq is a module */

	queue_autoload_drivers();

#endif

}

EXPORT_SYMBOL(snd_seq_autoload_init);



void snd_seq_autoload_exit(void)

{

	atomic_inc(&snd_seq_in_init);

}

EXPORT_SYMBOL(snd_seq_autoload_exit);



void snd_seq_device_load_drivers(void)

{

	queue_autoload_drivers();

	flush_work(&autoload_work);

}

EXPORT_SYMBOL(snd_seq_device_load_drivers);

#define cancel_autoload_drivers()	cancel_work_sync(&autoload_work)

#else

#define queue_autoload_drivers() /* NOP */

#define cancel_autoload_drivers() /* NOP */

#endif



/*

 * device management

 */

static int snd_seq_device_dev_free(struct snd_device *device)

{

	struct snd_seq_device *dev = device->device_data;



	cancel_autoload_drivers();

	put_device(&dev->dev);

	return 0;

}



static int snd_seq_device_dev_register(struct snd_device *device)

{

	struct snd_seq_device *dev = device->device_data;

	int err;



	err = device_add(&dev->dev);

	if (err < 0)

		return err;

	if (!dev->dev.driver)

		queue_autoload_drivers();

	return 0;

}



static int snd_seq_device_dev_disconnect(struct snd_device *device)

{

	struct snd_seq_device *dev = device->device_data;



	device_del(&dev->dev);

	return 0;

}



static void snd_seq_dev_release(struct device *dev)

{

	struct snd_seq_device *sdev = to_seq_dev(dev);



	if (sdev->private_free)

		sdev->private_free(sdev);

	kfree(sdev);

}



/*

 * register a sequencer device

 * card = card info

 * device = device number (if any)

 * id = id of driver

 * result = return pointer (NULL allowed if unnecessary)

 */

int snd_seq_device_new(struct snd_card *card, int device, const char *id,

		       int argsize, struct snd_seq_device **result)

{

	struct snd_seq_device *dev;

	int err;

	static struct snd_device_ops dops = {

		.dev_free = snd_seq_device_dev_free,

		.dev_register = snd_seq_device_dev_register,

		.dev_disconnect = snd_seq_device_dev_disconnect,

	};



	if (result)

		*result = NULL;



	if (snd_BUG_ON(!id))

		return -EINVAL;



	dev = kzalloc(sizeof(*dev) + argsize, GFP_KERNEL);

	if (!dev)

		return -ENOMEM;



	/* set up device info */

	dev->card = card;

	dev->device = device;

	dev->id = id;

	dev->argsize = argsize;



	device_initialize(&dev->dev);

	dev->dev.parent = &card->card_dev;

	dev->dev.bus = &snd_seq_bus_type;

	dev->dev.release = snd_seq_dev_release;

	dev_set_name(&dev->dev, "%s-%d-%d", dev->id, card->number, device);



	/* add this device to the list */

	err = snd_device_new(card, SNDRV_DEV_SEQUENCER, dev, &dops);

	if (err < 0) {

		put_device(&dev->dev);

		return err;

	}



	if (result)

		*result = dev;



	return 0;

}

EXPORT_SYMBOL(snd_seq_device_new);



/*

 * driver registration

 */

int __snd_seq_driver_register(struct snd_seq_driver *drv, struct module *mod)

{

	if (WARN_ON(!drv->driver.name || !drv->id))

		return -EINVAL;

	drv->driver.bus = &snd_seq_bus_type;

	drv->driver.owner = mod;

	return driver_register(&drv->driver);

}

EXPORT_SYMBOL_GPL(__snd_seq_driver_register);



void snd_seq_driver_unregister(struct snd_seq_driver *drv)

{

	driver_unregister(&drv->driver);

}

EXPORT_SYMBOL_GPL(snd_seq_driver_unregister);



/*

 * module part

 */



static int __init seq_dev_proc_init(void)

{

#ifdef CONFIG_SND_PROC_FS

	info_entry = snd_info_create_module_entry(THIS_MODULE, "drivers",

						  snd_seq_root);

	if (info_entry == NULL)

		return -ENOMEM;

	info_entry->content = SNDRV_INFO_CONTENT_TEXT;

	info_entry->c.text.read = snd_seq_device_info;

	if (snd_info_register(info_entry) < 0) {

		snd_info_free_entry(info_entry);

		return -ENOMEM;

	}

#endif

	return 0;

}



static int __init alsa_seq_device_init(void)

{

	int err;



	err = bus_register(&snd_seq_bus_type);

	if (err < 0)

		return err;

	err = seq_dev_proc_init();

	if (err < 0)

		bus_unregister(&snd_seq_bus_type);

	return err;

}



static void __exit alsa_seq_device_exit(void)

{

#ifdef CONFIG_MODULES

	cancel_work_sync(&autoload_work);

#endif

#ifdef CONFIG_SND_PROC_FS

	snd_info_free_entry(info_entry);

#endif

	bus_unregister(&snd_seq_bus_type);

}



subsys_initcall(alsa_seq_device_init)

module_exit(alsa_seq_device_exit)

#include "cache.h"

#include "config.h"

#include "credential.h"

#include "string-list.h"

#include "run-command.h"

#include "url.h"

#include "prompt.h"



void credential_init(struct credential *c)

{

	memset(c, 0, sizeof(*c));

	c->helpers.strdup_strings = 1;

}



void credential_clear(struct credential *c)

{

	free(c->protocol);

	free(c->host);

	free(c->path);

	free(c->username);

	free(c->password);

	string_list_clear(&c->helpers, 0);



	credential_init(c);

}



int credential_match(const struct credential *want,

		     const struct credential *have)

{

#define CHECK(x) (!want->x || (have->x && !strcmp(want->x, have->x)))

	return CHECK(protocol) &&

	       CHECK(host) &&

	       CHECK(path) &&

	       CHECK(username);

#undef CHECK

}



static int credential_config_callback(const char *var, const char *value,

				      void *data)

{

	struct credential *c = data;

	const char *key, *dot;



	if (!skip_prefix(var, "credential.", &key))

		return 0;



	if (!value)

		return config_error_nonbool(var);



	dot = strrchr(key, '.');

	if (dot) {

		struct credential want = CREDENTIAL_INIT;

		char *url = xmemdupz(key, dot - key);

		int matched;



		credential_from_url(&want, url);

		matched = credential_match(&want, c);



		credential_clear(&want);

		free(url);



		if (!matched)

			return 0;

		key = dot + 1;

	}



	if (!strcmp(key, "helper")) {

		if (*value)

			string_list_append(&c->helpers, value);

		else

			string_list_clear(&c->helpers, 0);

	} else if (!strcmp(key, "username")) {

		if (!c->username)

			c->username = xstrdup(value);

	}

	else if (!strcmp(key, "usehttppath"))

		c->use_http_path = git_config_bool(var, value);



	return 0;

}



static int proto_is_http(const char *s)

{

	if (!s)

		return 0;

	return !strcmp(s, "https") || !strcmp(s, "http");

}



static void credential_apply_config(struct credential *c)

{

	if (!c->host)

		die(_("refusing to work with credential missing host field"));

	if (!c->protocol)

		die(_("refusing to work with credential missing protocol field"));



	if (c->configured)

		return;

	git_config(credential_config_callback, c);

	c->configured = 1;



	if (!c->use_http_path && proto_is_http(c->protocol)) {

		FREE_AND_NULL(c->path);

	}

}



static void credential_describe(struct credential *c, struct strbuf *out)

{

	if (!c->protocol)

		return;

	strbuf_addf(out, "%s://", c->protocol);

	if (c->username && *c->username)

		strbuf_addf(out, "%s@", c->username);

	if (c->host)

		strbuf_addstr(out, c->host);

	if (c->path)

		strbuf_addf(out, "/%s", c->path);

}



static char *credential_ask_one(const char *what, struct credential *c,

				int flags)

{

	struct strbuf desc = STRBUF_INIT;

	struct strbuf prompt = STRBUF_INIT;

	char *r;



	credential_describe(c, &desc);

	if (desc.len)

		strbuf_addf(&prompt, "%s for '%s': ", what, desc.buf);

	else

		strbuf_addf(&prompt, "%s: ", what);



	r = git_prompt(prompt.buf, flags);



	strbuf_release(&desc);

	strbuf_release(&prompt);

	return xstrdup(r);

}



static void credential_getpass(struct credential *c)

{

	if (!c->username)

		c->username = credential_ask_one("Username", c,

						 PROMPT_ASKPASS|PROMPT_ECHO);

	if (!c->password)

		c->password = credential_ask_one("Password", c,

						 PROMPT_ASKPASS);

}



int credential_read(struct credential *c, FILE *fp)

{

	struct strbuf line = STRBUF_INIT;



	while (strbuf_getline_lf(&line, fp) != EOF) {

		char *key = line.buf;

		char *value = strchr(key, '=');



		if (!line.len)

			break;



		if (!value) {

			warning("invalid credential line: %s", key);

			strbuf_release(&line);

			return -1;

		}

		*value++ = '\0';



		if (!strcmp(key, "username")) {

			free(c->username);

			c->username = xstrdup(value);

		} else if (!strcmp(key, "password")) {

			free(c->password);

			c->password = xstrdup(value);

		} else if (!strcmp(key, "protocol")) {

			free(c->protocol);

			c->protocol = xstrdup(value);

		} else if (!strcmp(key, "host")) {

			free(c->host);

			c->host = xstrdup(value);

		} else if (!strcmp(key, "path")) {

			free(c->path);

			c->path = xstrdup(value);

		} else if (!strcmp(key, "url")) {

			credential_from_url(c, value);

		} else if (!strcmp(key, "quit")) {

			c->quit = !!git_config_bool("quit", value);

		}

		/*

		 * Ignore other lines; we don't know what they mean, but

		 * this future-proofs us when later versions of git do

		 * learn new lines, and the helpers are updated to match.

		 */

	}



	strbuf_release(&line);

	return 0;

}



static void credential_write_item(FILE *fp, const char *key, const char *value,

				  int required)

{

	if (!value && required)

		BUG("credential value for %s is missing", key);

	if (!value)

		return;

	if (strchr(value, '\n'))

		die("credential value for %s contains newline", key);

	fprintf(fp, "%s=%s\n", key, value);

}



void credential_write(const struct credential *c, FILE *fp)

{

	credential_write_item(fp, "protocol", c->protocol, 1);

	credential_write_item(fp, "host", c->host, 1);

	credential_write_item(fp, "path", c->path, 0);

	credential_write_item(fp, "username", c->username, 0);

	credential_write_item(fp, "password", c->password, 0);

}



static int run_credential_helper(struct credential *c,

				 const char *cmd,

				 int want_output)

{

	struct child_process helper = CHILD_PROCESS_INIT;

	const char *argv[] = { NULL, NULL };

	FILE *fp;



	argv[0] = cmd;

	helper.argv = argv;

	helper.use_shell = 1;

	helper.in = -1;

	if (want_output)

		helper.out = -1;

	else

		helper.no_stdout = 1;



	if (start_command(&helper) < 0)

		return -1;



	fp = xfdopen(helper.in, "w");

	credential_write(c, fp);

	fclose(fp);



	if (want_output) {

		int r;

		fp = xfdopen(helper.out, "r");

		r = credential_read(c, fp);

		fclose(fp);

		if (r < 0) {

			finish_command(&helper);

			return -1;

		}

	}



	if (finish_command(&helper))

		return -1;

	return 0;

}



static int credential_do(struct credential *c, const char *helper,

			 const char *operation)

{

	struct strbuf cmd = STRBUF_INIT;

	int r;



	if (helper[0] == '!')

		strbuf_addstr(&cmd, helper + 1);

	else if (is_absolute_path(helper))

		strbuf_addstr(&cmd, helper);

	else

		strbuf_addf(&cmd, "git credential-%s", helper);



	strbuf_addf(&cmd, " %s", operation);

	r = run_credential_helper(c, cmd.buf, !strcmp(operation, "get"));



	strbuf_release(&cmd);

	return r;

}



void credential_fill(struct credential *c)

{

	int i;



	if (c->username && c->password)

		return;



	credential_apply_config(c);



	for (i = 0; i < c->helpers.nr; i++) {

		credential_do(c, c->helpers.items[i].string, "get");

		if (c->username && c->password)

			return;

		if (c->quit)

			die("credential helper '%s' told us to quit",

			    c->helpers.items[i].string);

	}



	credential_getpass(c);

	if (!c->username && !c->password)

		die("unable to get password from user");

}



void credential_approve(struct credential *c)

{

	int i;



	if (c->approved)

		return;

	if (!c->username || !c->password)

		return;



	credential_apply_config(c);



	for (i = 0; i < c->helpers.nr; i++)

		credential_do(c, c->helpers.items[i].string, "store");

	c->approved = 1;

}



void credential_reject(struct credential *c)

{

	int i;



	credential_apply_config(c);



	for (i = 0; i < c->helpers.nr; i++)

		credential_do(c, c->helpers.items[i].string, "erase");



	FREE_AND_NULL(c->username);

	FREE_AND_NULL(c->password);

	c->approved = 0;

}



static int check_url_component(const char *url, int quiet,

			       const char *name, const char *value)

{

	if (!value)

		return 0;

	if (!strchr(value, '\n'))

		return 0;



	if (!quiet)

		warning(_("url contains a newline in its %s component: %s"),

			name, url);

	return -1;

}



int credential_from_url_gently(struct credential *c, const char *url,

			       int quiet)

{

	const char *at, *colon, *cp, *slash, *host, *proto_end;



	credential_clear(c);



	/*

	 * Match one of:

	 *   (1) proto://<host>/...

	 *   (2) proto://<user>@<host>/...

	 *   (3) proto://<user>:<pass>@<host>/...

	 */

	proto_end = strstr(url, "://");

	if (!proto_end)

		return 0;

	cp = proto_end + 3;

	at = strchr(cp, '@');

	colon = strchr(cp, ':');

	slash = strchrnul(cp, '/');



	if (!at || slash <= at) {

		/* Case (1) */

		host = cp;

	}

	else if (!colon || at <= colon) {

		/* Case (2) */

		c->username = url_decode_mem(cp, at - cp);

		host = at + 1;

	} else {

		/* Case (3) */

		c->username = url_decode_mem(cp, colon - cp);

		c->password = url_decode_mem(colon + 1, at - (colon + 1));

		host = at + 1;

	}



	if (proto_end - url > 0)

		c->protocol = xmemdupz(url, proto_end - url);

	c->host = url_decode_mem(host, slash - host);

	/* Trim leading and trailing slashes from path */

	while (*slash == '/')

		slash++;

	if (*slash) {

		char *p;

		c->path = url_decode(slash);

		p = c->path + strlen(c->path) - 1;

		while (p > c->path && *p == '/')

			*p-- = '\0';

	}



	if (check_url_component(url, quiet, "username", c->username) < 0 ||

	    check_url_component(url, quiet, "password", c->password) < 0 ||

	    check_url_component(url, quiet, "protocol", c->protocol) < 0 ||

	    check_url_component(url, quiet, "host", c->host) < 0 ||

	    check_url_component(url, quiet, "path", c->path) < 0)

		return -1;



	return 0;

}



void credential_from_url(struct credential *c, const char *url)

{

	if (credential_from_url_gently(c, url, 0) < 0)

		die(_("credential url cannot be parsed: %s"), url);

}

/**

