	struct gfs2_holder gh;

	bool need_unlock = false;

	struct posix_acl *acl;



	if (!gfs2_glock_is_locked_by_me(ip->i_gl)) {

		int ret = gfs2_glock_nq_init(ip->i_gl, LM_ST_SHARED,

					     LM_FLAG_ANY, &gh);

		if (ret)

			return ERR_PTR(ret);

		need_unlock = true;

	}

	acl = __gfs2_get_acl(inode, type);

	if (need_unlock)

		gfs2_glock_dq_uninit(&gh);

	return acl;

}



int __gfs2_set_acl(struct inode *inode, struct posix_acl *acl, int type)

{

	int error;

	int len;

	char *data;

	const char *name = gfs2_acl_name(type);



	if (acl && acl->a_count > GFS2_ACL_MAX_ENTRIES(GFS2_SB(inode)))

		return -E2BIG;



	if (type == ACL_TYPE_ACCESS) {

		umode_t mode = inode->i_mode;



		error = posix_acl_equiv_mode(acl, &mode);

		if (error < 0)

			return error;



		if (error == 0)

			acl = NULL;



		if (mode != inode->i_mode) {

			inode->i_mode = mode;

			mark_inode_dirty(inode);

		}

	}



	if (acl) {

		len = posix_acl_to_xattr(&init_user_ns, acl, NULL, 0);

		if (len == 0)

			return 0;

		data = kmalloc(len, GFP_NOFS);

		if (data == NULL)

			return -ENOMEM;

		error = posix_acl_to_xattr(&init_user_ns, acl, data, len);

		if (error < 0)

			goto out;

	} else {

		data = NULL;

		len = 0;

	}



	error = __gfs2_xattr_set(inode, name, data, len, 0, GFS2_EATYPE_SYS);

	if (error)

		goto out;

	set_cached_acl(inode, type, acl);

out:

	kfree(data);

	return error;

}



int gfs2_set_acl(struct inode *inode, struct posix_acl *acl, int type)

{

	struct gfs2_inode *ip = GFS2_I(inode);

	struct gfs2_holder gh;

	bool need_unlock = false;

	int ret;



	ret = gfs2_rsqa_alloc(ip);

	if (ret)

		return ret;



	if (!gfs2_glock_is_locked_by_me(ip->i_gl)) {

		ret = gfs2_glock_nq_init(ip->i_gl, LM_ST_EXCLUSIVE, 0, &gh);

		if (ret)

			return ret;

		need_unlock = true;

	}

	ret = __gfs2_set_acl(inode, acl, type);

	if (need_unlock)

		gfs2_glock_dq_uninit(&gh);

	return ret;

}

/*

 * Functions related to mapping data to requests

 */

#include <linux/kernel.h>

#include <linux/module.h>

#include <linux/bio.h>

#include <linux/blkdev.h>

#include <linux/uio.h>



#include "blk.h"



/*

 * Append a bio to a passthrough request.  Only works can be merged into

 * the request based on the driver constraints.

 */

int blk_rq_append_bio(struct request *rq, struct bio *bio)

{

	if (!rq->bio) {

		blk_rq_bio_prep(rq->q, rq, bio);

	} else {

		if (!ll_back_merge_fn(rq->q, rq, bio))

			return -EINVAL;



		rq->biotail->bi_next = bio;

		rq->biotail = bio;

		rq->__data_len += bio->bi_iter.bi_size;

	}



	return 0;

}

EXPORT_SYMBOL(blk_rq_append_bio);



static int __blk_rq_unmap_user(struct bio *bio)

{

	int ret = 0;



	if (bio) {

		if (bio_flagged(bio, BIO_USER_MAPPED))

			bio_unmap_user(bio);

		else

			ret = bio_uncopy_user(bio);

	}



	return ret;

}



static int __blk_rq_map_user_iov(struct request *rq,

		struct rq_map_data *map_data, struct iov_iter *iter,

		gfp_t gfp_mask, bool copy)

{

	struct request_queue *q = rq->q;

	struct bio *bio, *orig_bio;

	int ret;



	if (copy)

		bio = bio_copy_user_iov(q, map_data, iter, gfp_mask);

	else

		bio = bio_map_user_iov(q, iter, gfp_mask);



	if (IS_ERR(bio))

		return PTR_ERR(bio);



	if (map_data && map_data->null_mapped)

		bio_set_flag(bio, BIO_NULL_MAPPED);



	iov_iter_advance(iter, bio->bi_iter.bi_size);

	if (map_data)

		map_data->offset += bio->bi_iter.bi_size;



	orig_bio = bio;

	blk_queue_bounce(q, &bio);



	/*

	 * We link the bounce buffer in and could have to traverse it

	 * later so we have to get a ref to prevent it from being freed

	 */

	bio_get(bio);



	ret = blk_rq_append_bio(rq, bio);

	if (ret) {

		bio_endio(bio);

		__blk_rq_unmap_user(orig_bio);

		bio_put(bio);

		return ret;

	}



	return 0;

}



/**

 * blk_rq_map_user_iov - map user data to a request, for REQ_TYPE_BLOCK_PC usage

 * @q:		request queue where request should be inserted

 * @rq:		request to map data to

 * @map_data:   pointer to the rq_map_data holding pages (if necessary)

 * @iter:	iovec iterator

 * @gfp_mask:	memory allocation flags

 *

 * Description:

 *    Data will be mapped directly for zero copy I/O, if possible. Otherwise

 *    a kernel bounce buffer is used.

 *

 *    A matching blk_rq_unmap_user() must be issued at the end of I/O, while

 *    still in process context.

 *

 *    Note: The mapped bio may need to be bounced through blk_queue_bounce()

 *    before being submitted to the device, as pages mapped may be out of

 *    reach. It's the callers responsibility to make sure this happens. The

 *    original bio must be passed back in to blk_rq_unmap_user() for proper

 *    unmapping.

 */

int blk_rq_map_user_iov(struct request_queue *q, struct request *rq,

			struct rq_map_data *map_data,

			const struct iov_iter *iter, gfp_t gfp_mask)

{

	bool copy = false;

	unsigned long align = q->dma_pad_mask | queue_dma_alignment(q);

	struct bio *bio = NULL;

	struct iov_iter i;

	int ret;



	if (!iter_is_iovec(iter))

		goto fail;



	if (map_data)

		copy = true;

	else if (iov_iter_alignment(iter) & align)

		copy = true;

	else if (queue_virt_boundary(q))

		copy = queue_virt_boundary(q) & iov_iter_gap_alignment(iter);



	i = *iter;

	do {

		ret =__blk_rq_map_user_iov(rq, map_data, &i, gfp_mask, copy);

		if (ret)

			goto unmap_rq;

		if (!bio)

			bio = rq->bio;

	} while (iov_iter_count(&i));



	if (!bio_flagged(bio, BIO_USER_MAPPED))

		rq->cmd_flags |= REQ_COPY_USER;

	return 0;



unmap_rq:

	__blk_rq_unmap_user(bio);

fail:

	rq->bio = NULL;

	return -EINVAL;

}

EXPORT_SYMBOL(blk_rq_map_user_iov);



int blk_rq_map_user(struct request_queue *q, struct request *rq,

		    struct rq_map_data *map_data, void __user *ubuf,

		    unsigned long len, gfp_t gfp_mask)

{

	struct iovec iov;

	struct iov_iter i;

	int ret = import_single_range(rq_data_dir(rq), ubuf, len, &iov, &i);



	if (unlikely(ret < 0))

		return ret;



	return blk_rq_map_user_iov(q, rq, map_data, &i, gfp_mask);

}

EXPORT_SYMBOL(blk_rq_map_user);



/**

 * blk_rq_unmap_user - unmap a request with user data

 * @bio:	       start of bio list

 *

 * Description:

 *    Unmap a rq previously mapped by blk_rq_map_user(). The caller must

 *    supply the original rq->bio from the blk_rq_map_user() return, since

 *    the I/O completion may have changed rq->bio.

 */

int blk_rq_unmap_user(struct bio *bio)

{

	struct bio *mapped_bio;

	int ret = 0, ret2;



	while (bio) {

		mapped_bio = bio;

		if (unlikely(bio_flagged(bio, BIO_BOUNCED)))

			mapped_bio = bio->bi_private;



		ret2 = __blk_rq_unmap_user(mapped_bio);

		if (ret2 && !ret)

			ret = ret2;



		mapped_bio = bio;

		bio = bio->bi_next;

		bio_put(mapped_bio);

	}



	return ret;

}

EXPORT_SYMBOL(blk_rq_unmap_user);



/**

 * blk_rq_map_kern - map kernel data to a request, for REQ_TYPE_BLOCK_PC usage

 * @q:		request queue where request should be inserted

 * @rq:		request to fill

 * @kbuf:	the kernel buffer

 * @len:	length of user data

 * @gfp_mask:	memory allocation flags

 *

 * Description:

 *    Data will be mapped directly if possible. Otherwise a bounce

 *    buffer is used. Can be called multiple times to append multiple

 *    buffers.

 */

int blk_rq_map_kern(struct request_queue *q, struct request *rq, void *kbuf,

		    unsigned int len, gfp_t gfp_mask)

{

	int reading = rq_data_dir(rq) == READ;

	unsigned long addr = (unsigned long) kbuf;

	int do_copy = 0;

	struct bio *bio;

	int ret;



	if (len > (queue_max_hw_sectors(q) << 9))

		return -EINVAL;

	if (!len || !kbuf)

		return -EINVAL;



	do_copy = !blk_rq_aligned(q, addr, len) || object_is_on_stack(kbuf);

	if (do_copy)

		bio = bio_copy_kern(q, kbuf, len, gfp_mask, reading);

	else

		bio = bio_map_kern(q, kbuf, len, gfp_mask);



	if (IS_ERR(bio))

		return PTR_ERR(bio);



	if (!reading)

		bio_set_op_attrs(bio, REQ_OP_WRITE, 0);



	if (do_copy)

		rq->cmd_flags |= REQ_COPY_USER;



	ret = blk_rq_append_bio(rq, bio);

	if (unlikely(ret)) {

		/* request is too big */

		bio_put(bio);

		return ret;

	}



	blk_queue_bounce(q, &rq->bio);

	return 0;

}

EXPORT_SYMBOL(blk_rq_map_kern);

/* Crop support

 * manual crop using a gdRect or automatic crop using a background

 * color (automatic detections or using either the transparent color,

 * black or white).

 * An alternative method allows to crop using a given color and a

 * threshold. It works relatively well but it can be improved.

 * Maybe L*a*b* and Delta-E will give better results (and a better

 * granularity).

 */



#ifdef HAVE_CONFIG_H

#include "config.h"

#endif



#include <stdlib.h>

#include "gd.h"

#include "gd_color.h"



static int gdGuessBackgroundColorFromCorners(gdImagePtr im, int *color);



BGD_DECLARE(gdImagePtr) gdImageCrop(gdImagePtr src, const gdRect *crop)

{

	gdImagePtr dst;



	dst = gdImageCreateTrueColor(crop->width, crop->height);

	if (!dst) return NULL;

	gdImageCopy(dst, src, 0, 0, crop->x, crop->y, crop->width, crop->height);



	return dst;

}



BGD_DECLARE(gdImagePtr) gdImageCropAuto(gdImagePtr im, const unsigned int mode)

{

	const int width = gdImageSX(im);

	const int height = gdImageSY(im);



	int x,y;

	int color, match;

	gdRect crop;



	crop.x = 0;

	crop.y = 0;

	crop.width = 0;

	crop.height = 0;



	switch (mode) {

	case GD_CROP_TRANSPARENT:

		color = gdImageGetTransparent(im);

		break;



	case GD_CROP_BLACK:

		color = gdImageColorClosestAlpha(im, 0, 0, 0, 0);

		break;



	case GD_CROP_WHITE:

		color = gdImageColorClosestAlpha(im, 255, 255, 255, 0);

		break;



	case GD_CROP_SIDES:

		gdGuessBackgroundColorFromCorners(im, &color);

		break;



	case GD_CROP_DEFAULT:

	default:

		color = gdImageGetTransparent(im);

		break;

	}



	/* TODO: Add gdImageGetRowPtr and works with ptr at the row level

	 * for the true color and palette images

	 * new formats will simply work with ptr

	 */

	match = 1;

	for (y = 0; match && y < height; y++) {

		for (x = 0; match && x < width; x++) {

			match = (color == gdImageGetPixel(im, x,y));

		}

	}



	/* Nothing to do > bye

	 * Duplicate the image?

	 */

	if (y == height - 1) {

		return NULL;

	}



	crop.y = y -1;

	match = 1;

	for (y = height - 1; match && y >= 0; y--) {

		for (x = 0; match && x < width; x++) {

			match = (color == gdImageGetPixel(im, x,y));

		}

	}



	if (y == 0) {

		crop.height = height - crop.y + 1;

	} else {

		crop.height = y - crop.y + 2;

	}



	match = 1;

	for (x = 0; match && x < width; x++) {

		for (y = 0; match && y < crop.y + crop.height - 1; y++) {

			match = (color == gdImageGetPixel(im, x,y));

		}

	}

	crop.x = x - 1;



	match = 1;

	for (x = width - 1; match && x >= 0; x--) {

		for (y = 0; match &&  y < crop.y + crop.height - 1; y++) {

			match = (color == gdImageGetPixel(im, x,y));

		}

	}

	crop.width = x - crop.x + 2;



	return gdImageCrop(im, &crop);

}



BGD_DECLARE(gdImagePtr) gdImageCropThreshold(gdImagePtr im, const unsigned int color, const float threshold)

{

	const int width = gdImageSX(im);

	const int height = gdImageSY(im);



	int x,y;

	int match;

	gdRect crop;



	crop.x = 0;

	crop.y = 0;

	crop.width = 0;

	crop.height = 0;



	/* Pierre: crop everything sounds bad */

	if (threshold > 100.0) {

		return NULL;

	}



	if (color < 0 || (!gdImageTrueColor(im) && color >= gdImageColorsTotal(im))) {

		return NULL;

	}



	/* TODO: Add gdImageGetRowPtr and works with ptr at the row level

	 * for the true color and palette images

	 * new formats will simply work with ptr

	 */

	match = 1;

	for (y = 0; match && y < height; y++) {

		for (x = 0; match && x < width; x++) {

			match = (gdColorMatch(im, color, gdImageGetPixel(im, x,y), threshold)) > 0;

		}

	}



	/* Pierre

	 * Nothing to do > bye

	 * Duplicate the image?

	 */

	if (y == height - 1) {

		return NULL;

	}



	crop.y = y -1;

	match = 1;

	for (y = height - 1; match && y >= 0; y--) {

		for (x = 0; match && x < width; x++) {

			match = (gdColorMatch(im, color, gdImageGetPixel(im, x, y), threshold)) > 0;

		}

	}



	if (y == 0) {

		crop.height = height - crop.y + 1;

	} else {

		crop.height = y - crop.y + 2;

	}



	match = 1;

	for (x = 0; match && x < width; x++) {

		for (y = 0; match && y < crop.y + crop.height - 1; y++) {

			match = (gdColorMatch(im, color, gdImageGetPixel(im, x,y), threshold)) > 0;

		}

	}

	crop.x = x - 1;



	match = 1;

	for (x = width - 1; match && x >= 0; x--) {

		for (y = 0; match &&  y < crop.y + crop.height - 1; y++) {

			match = (gdColorMatch(im, color, gdImageGetPixel(im, x,y), threshold)) > 0;

		}

	}

	crop.width = x - crop.x + 2;



	return gdImageCrop(im, &crop);

}



/* This algorithm comes from pnmcrop (http://netpbm.sourceforge.net/)

 * Three steps:

 *  - if 3 corners are equal.

 *  - if two are equal.

 *  - Last solution: average the colors

 */

static int gdGuessBackgroundColorFromCorners(gdImagePtr im, int *color)

{

	const int tl = gdImageGetPixel(im, 0, 0);

	const int tr = gdImageGetPixel(im, gdImageSX(im) - 1, 0);

	const int bl = gdImageGetPixel(im, 0, gdImageSY(im) -1);

	const int br = gdImageGetPixel(im, gdImageSX(im) - 1, gdImageSY(im) -1);



	if (tr == bl && tr == br) {

		*color = tr;

		return 3;

	} else if (tl == bl && tl == br) {

		*color = tl;

		return 3;

	} else if (tl == tr &&  tl == br) {

		*color = tl;

		return 3;

	} else if (tl == tr &&  tl == bl) {

		*color = tl;

		return 3;

	} else if (tl == tr  || tl == bl || tl == br) {

		*color = tl;

		return 2;

	} else if (tr == bl) {

		*color = tr;

		return 2;

	} else if (br == bl) {

		*color = bl;

		return 2;

	} else {

		register int r,b,g,a;



		r = (int)(0.5f + (gdImageRed(im, tl) + gdImageRed(im, tr) + gdImageRed(im, bl) + gdImageRed(im, br)) / 4);

		g = (int)(0.5f + (gdImageGreen(im, tl) + gdImageGreen(im, tr) + gdImageGreen(im, bl) + gdImageGreen(im, br)) / 4);

		b = (int)(0.5f + (gdImageBlue(im, tl) + gdImageBlue(im, tr) + gdImageBlue(im, bl) + gdImageBlue(im, br)) / 4);

		a = (int)(0.5f + (gdImageAlpha(im, tl) + gdImageAlpha(im, tr) + gdImageAlpha(im, bl) + gdImageAlpha(im, br)) / 4);

		*color = gdImageColorClosestAlpha(im, r, g, b, a);

		return 0;

	}

}

#include "cache.h"

#include "config.h"

#include "credential.h"

#include "string-list.h"

#include "run-command.h"

#include "url.h"

#include "prompt.h"



void credential_init(struct credential *c)

{

	memset(c, 0, sizeof(*c));

	c->helpers.strdup_strings = 1;

}



void credential_clear(struct credential *c)

{

	free(c->protocol);

	free(c->host);

	free(c->path);

	free(c->username);

	free(c->password);

	string_list_clear(&c->helpers, 0);



	credential_init(c);

}



int credential_match(const struct credential *want,

		     const struct credential *have)

{

#define CHECK(x) (!want->x || (have->x && !strcmp(want->x, have->x)))

	return CHECK(protocol) &&

	       CHECK(host) &&

	       CHECK(path) &&

	       CHECK(username);

#undef CHECK

}



static int credential_config_callback(const char *var, const char *value,

				      void *data)

{

	struct credential *c = data;

	const char *key, *dot;



	if (!skip_prefix(var, "credential.", &key))

		return 0;



	if (!value)

		return config_error_nonbool(var);



	dot = strrchr(key, '.');

	if (dot) {

		struct credential want = CREDENTIAL_INIT;

		char *url = xmemdupz(key, dot - key);

		int matched;



		credential_from_url(&want, url);

		matched = credential_match(&want, c);



		credential_clear(&want);

		free(url);



		if (!matched)

			return 0;

		key = dot + 1;

	}



	if (!strcmp(key, "helper")) {

		if (*value)

			string_list_append(&c->helpers, value);

		else

			string_list_clear(&c->helpers, 0);

	} else if (!strcmp(key, "username")) {

		if (!c->username)

			c->username = xstrdup(value);

	}

	else if (!strcmp(key, "usehttppath"))

		c->use_http_path = git_config_bool(var, value);



	return 0;

}



static int proto_is_http(const char *s)

{

	if (!s)

		return 0;

	return !strcmp(s, "https") || !strcmp(s, "http");

}



static void credential_apply_config(struct credential *c)

{

	if (c->configured)

		return;

	git_config(credential_config_callback, c);

	c->configured = 1;



	if (!c->use_http_path && proto_is_http(c->protocol)) {

		FREE_AND_NULL(c->path);

	}

}



static void credential_describe(struct credential *c, struct strbuf *out)

{

	if (!c->protocol)

		return;

	strbuf_addf(out, "%s://", c->protocol);

	if (c->username && *c->username)

		strbuf_addf(out, "%s@", c->username);

	if (c->host)

		strbuf_addstr(out, c->host);

	if (c->path)

		strbuf_addf(out, "/%s", c->path);

}



static char *credential_ask_one(const char *what, struct credential *c,

				int flags)

{

	struct strbuf desc = STRBUF_INIT;

	struct strbuf prompt = STRBUF_INIT;

	char *r;



	credential_describe(c, &desc);

	if (desc.len)

		strbuf_addf(&prompt, "%s for '%s': ", what, desc.buf);

	else

		strbuf_addf(&prompt, "%s: ", what);



	r = git_prompt(prompt.buf, flags);



	strbuf_release(&desc);

	strbuf_release(&prompt);

	return xstrdup(r);

}



static void credential_getpass(struct credential *c)

{

	if (!c->username)

		c->username = credential_ask_one("Username", c,

						 PROMPT_ASKPASS|PROMPT_ECHO);

	if (!c->password)

		c->password = credential_ask_one("Password", c,

						 PROMPT_ASKPASS);

}



int credential_read(struct credential *c, FILE *fp)

{

	struct strbuf line = STRBUF_INIT;



	while (strbuf_getline_lf(&line, fp) != EOF) {

		char *key = line.buf;

		char *value = strchr(key, '=');



		if (!line.len)

			break;



		if (!value) {

			warning("invalid credential line: %s", key);

			strbuf_release(&line);

			return -1;

		}

		*value++ = '\0';



		if (!strcmp(key, "username")) {

			free(c->username);

			c->username = xstrdup(value);

		} else if (!strcmp(key, "password")) {

			free(c->password);

			c->password = xstrdup(value);

		} else if (!strcmp(key, "protocol")) {

			free(c->protocol);

			c->protocol = xstrdup(value);

		} else if (!strcmp(key, "host")) {

			free(c->host);

			c->host = xstrdup(value);

		} else if (!strcmp(key, "path")) {

			free(c->path);

			c->path = xstrdup(value);

		} else if (!strcmp(key, "url")) {

			credential_from_url(c, value);

		} else if (!strcmp(key, "quit")) {

			c->quit = !!git_config_bool("quit", value);

		}

		/*

		 * Ignore other lines; we don't know what they mean, but

		 * this future-proofs us when later versions of git do

		 * learn new lines, and the helpers are updated to match.

		 */

	}



	strbuf_release(&line);

	return 0;

}



static void credential_write_item(FILE *fp, const char *key, const char *value)

{

	if (!value)

		return;

	fprintf(fp, "%s=%s\n", key, value);

}



void credential_write(const struct credential *c, FILE *fp)

{

	credential_write_item(fp, "protocol", c->protocol);

	credential_write_item(fp, "host", c->host);

	credential_write_item(fp, "path", c->path);

	credential_write_item(fp, "username", c->username);

	credential_write_item(fp, "password", c->password);

}



static int run_credential_helper(struct credential *c,

				 const char *cmd,

				 int want_output)

{

	struct child_process helper = CHILD_PROCESS_INIT;

	const char *argv[] = { NULL, NULL };

	FILE *fp;



	argv[0] = cmd;

	helper.argv = argv;

	helper.use_shell = 1;

	helper.in = -1;

	if (want_output)

		helper.out = -1;

	else

		helper.no_stdout = 1;



	if (start_command(&helper) < 0)

		return -1;



	fp = xfdopen(helper.in, "w");

	credential_write(c, fp);

	fclose(fp);



	if (want_output) {

		int r;

		fp = xfdopen(helper.out, "r");

		r = credential_read(c, fp);

		fclose(fp);

		if (r < 0) {

			finish_command(&helper);

			return -1;

		}

	}



	if (finish_command(&helper))

		return -1;

	return 0;

}



static int credential_do(struct credential *c, const char *helper,

			 const char *operation)

{

	struct strbuf cmd = STRBUF_INIT;

	int r;



	if (helper[0] == '!')

		strbuf_addstr(&cmd, helper + 1);

	else if (is_absolute_path(helper))

		strbuf_addstr(&cmd, helper);

	else

		strbuf_addf(&cmd, "git credential-%s", helper);



	strbuf_addf(&cmd, " %s", operation);

	r = run_credential_helper(c, cmd.buf, !strcmp(operation, "get"));



	strbuf_release(&cmd);

	return r;

}



void credential_fill(struct credential *c)

{

	int i;



	if (c->username && c->password)

		return;



	credential_apply_config(c);



	for (i = 0; i < c->helpers.nr; i++) {

		credential_do(c, c->helpers.items[i].string, "get");

		if (c->username && c->password)

			return;

		if (c->quit)

			die("credential helper '%s' told us to quit",

			    c->helpers.items[i].string);

	}



	credential_getpass(c);

	if (!c->username && !c->password)

		die("unable to get password from user");

}



void credential_approve(struct credential *c)

{

	int i;



	if (c->approved)

		return;

	if (!c->username || !c->password)

		return;



	credential_apply_config(c);



	for (i = 0; i < c->helpers.nr; i++)

		credential_do(c, c->helpers.items[i].string, "store");

	c->approved = 1;

}



void credential_reject(struct credential *c)

{

	int i;



	credential_apply_config(c);



	for (i = 0; i < c->helpers.nr; i++)

		credential_do(c, c->helpers.items[i].string, "erase");



	FREE_AND_NULL(c->username);

	FREE_AND_NULL(c->password);

	c->approved = 0;

}



void credential_from_url(struct credential *c, const char *url)

{

	const char *at, *colon, *cp, *slash, *host, *proto_end;



	credential_clear(c);



	/*

	 * Match one of:

	 *   (1) proto://<host>/...

	 *   (2) proto://<user>@<host>/...

	 *   (3) proto://<user>:<pass>@<host>/...

	 */

	proto_end = strstr(url, "://");

	if (!proto_end)

		return;

	cp = proto_end + 3;

	at = strchr(cp, '@');

	colon = strchr(cp, ':');

	slash = strchrnul(cp, '/');



	if (!at || slash <= at) {

		/* Case (1) */

		host = cp;

	}

	else if (!colon || at <= colon) {

		/* Case (2) */

		c->username = url_decode_mem(cp, at - cp);

		host = at + 1;

	} else {

		/* Case (3) */

		c->username = url_decode_mem(cp, colon - cp);

		c->password = url_decode_mem(colon + 1, at - (colon + 1));

		host = at + 1;

	}



	if (proto_end - url > 0)

		c->protocol = xmemdupz(url, proto_end - url);

	if (slash - host > 0)

		c->host = url_decode_mem(host, slash - host);

	/* Trim leading and trailing slashes from path */

	while (*slash == '/')

		slash++;

	if (*slash) {

		char *p;

		c->path = url_decode(slash);

		p = c->path + strlen(c->path) - 1;

		while (p > c->path && *p == '/')

			*p-- = '\0';

	}

}

