const op_def zstring_op_defs[] =

{

    {"1.bytestring", zbytestring},

    {"2anchorsearch", zanchorsearch},

    {"1.namestring", znamestring},

    {"2search", zsearch},

    {"2rsearch", zrsearch},

    {"1string", zstring},

    {"2.stringbreak", zstringbreak},

    {"2.stringmatch", zstringmatch},

    op_def_end(0)

};

