   * for a NULL key */ \

  /* \

  if (G_UNLIKELY (ch == 0)) \

    return FALSE; \

   */ \

 \

  if (bsearch (GUINT_TO_POINTER (ch), \

               _pango_##name##_table, \

               G_N_ELEMENTS (_pango_##name##_table), \

               sizeof _pango_##name##_table[0], \

	       interval_compare)) \

    return TRUE; \

 \

  return FALSE; \

}



