#include <linux/personality.h>

#include <linux/mm.h>

#include <linux/random.h>

#include <linux/limits.h>

#include <linux/sched.h>

#include <asm/elf.h>



struct va_alignment __read_mostly va_align = {

	.flags = -1,

};



static unsigned long stack_maxrandom_size(void)

{

	unsigned long max = 0;

	if ((current->flags & PF_RANDOMIZE) &&

		!(current->personality & ADDR_NO_RANDOMIZE)) {

		max = ((-1UL) & STACK_RND_MASK) << PAGE_SHIFT;

	}



	return max;

}



/*

 * Top of mmap area (just below the process stack).

 *

 * Leave an at least ~128 MB hole with possible stack randomization.

 */

#define MIN_GAP (128*1024*1024UL + stack_maxrandom_size())

#define MAX_GAP (TASK_SIZE/6*5)



static int mmap_is_legacy(void)

{

	if (current->personality & ADDR_COMPAT_LAYOUT)

		return 1;



	if (rlimit(RLIMIT_STACK) == RLIM_INFINITY)

		return 1;



	return sysctl_legacy_va_layout;

}



static unsigned long mmap_rnd(void)

{

	unsigned long rnd = 0;



	/*

	*  8 bits of randomness in 32bit mmaps, 20 address space bits

	* 28 bits of randomness in 64bit mmaps, 40 address space bits

	*/

	if (current->flags & PF_RANDOMIZE) {

		if (mmap_is_ia32())

			rnd = get_random_int() % (1<<8);

		else

			rnd = get_random_int() % (1<<28);

	}

	return rnd << PAGE_SHIFT;

}



static unsigned long mmap_base(void)

{

	unsigned long gap = rlimit(RLIMIT_STACK);



	if (gap < MIN_GAP)

		gap = MIN_GAP;

	else if (gap > MAX_GAP)

		gap = MAX_GAP;



	return PAGE_ALIGN(TASK_SIZE - gap - mmap_rnd());

}



/*

 * Bottom-up (legacy) layout on X86_32 did not support randomization, X86_64

 * does, but not when emulating X86_32

 */

static unsigned long mmap_legacy_base(void)

{

	if (mmap_is_ia32())

		return TASK_UNMAPPED_BASE;

	else

		return TASK_UNMAPPED_BASE + mmap_rnd();

}



/*

 * This function, called very early during the creation of a new

 * process VM image, sets up which VM layout function to use:

 */

void arch_pick_mmap_layout(struct mm_struct *mm)

{

	mm->mmap_legacy_base = mmap_legacy_base();

	mm->mmap_base = mmap_base();



	if (mmap_is_legacy()) {

		mm->mmap_base = mm->mmap_legacy_base;

		mm->get_unmapped_area = arch_get_unmapped_area;

	} else {

		mm->get_unmapped_area = arch_get_unmapped_area_topdown;

	}

}

#include <xml_relax_ng.h>



static void dealloc(xmlRelaxNGPtr schema)

{

  NOKOGIRI_DEBUG_START(schema);

  xmlRelaxNGFree(schema);

  NOKOGIRI_DEBUG_END(schema);

}



/*

 * call-seq:

 *  validate_document(document)

 *

 * Validate a Nokogiri::XML::Document against this RelaxNG schema.

 */

static VALUE validate_document(VALUE self, VALUE document)

{

  xmlDocPtr doc;

  xmlRelaxNGPtr schema;

  VALUE errors;

  xmlRelaxNGValidCtxtPtr valid_ctxt;



  Data_Get_Struct(self, xmlRelaxNG, schema);

  Data_Get_Struct(document, xmlDoc, doc);



  errors = rb_ary_new();



  valid_ctxt = xmlRelaxNGNewValidCtxt(schema);



  if(NULL == valid_ctxt) {

    /* we have a problem */

    rb_raise(rb_eRuntimeError, "Could not create a validation context");

  }



#ifdef HAVE_XMLRELAXNGSETVALIDSTRUCTUREDERRORS

  xmlRelaxNGSetValidStructuredErrors(

    valid_ctxt,

    Nokogiri_error_array_pusher,

    (void *)errors

  );

#endif



  xmlRelaxNGValidateDoc(valid_ctxt, doc);



  xmlRelaxNGFreeValidCtxt(valid_ctxt);



  return errors;

}



/*

 * call-seq:

 *  read_memory(string)

 *

 * Create a new RelaxNG from the contents of +string+

 */

static VALUE read_memory(VALUE klass, VALUE content)

{

  xmlRelaxNGParserCtxtPtr ctx = xmlRelaxNGNewMemParserCtxt(

      (const char *)StringValuePtr(content),

      (int)RSTRING_LEN(content)

  );

  xmlRelaxNGPtr schema;

  VALUE errors = rb_ary_new();

  VALUE rb_schema;



  xmlSetStructuredErrorFunc((void *)errors, Nokogiri_error_array_pusher);



#ifdef HAVE_XMLRELAXNGSETPARSERSTRUCTUREDERRORS

  xmlRelaxNGSetParserStructuredErrors(

    ctx,

    Nokogiri_error_array_pusher,

    (void *)errors

  );

#endif



  schema = xmlRelaxNGParse(ctx);



  xmlSetStructuredErrorFunc(NULL, NULL);

  xmlRelaxNGFreeParserCtxt(ctx);



  if(NULL == schema) {

    xmlErrorPtr error = xmlGetLastError();

    if(error)

      Nokogiri_error_raise(NULL, error);

    else

      rb_raise(rb_eRuntimeError, "Could not parse document");



    return Qnil;

  }



  rb_schema = Data_Wrap_Struct(klass, 0, dealloc, schema);

  rb_iv_set(rb_schema, "@errors", errors);



  return rb_schema;

}



/*

 * call-seq:

 *  from_document(doc)

 *

 * Create a new RelaxNG schema from the Nokogiri::XML::Document +doc+

 */

static VALUE from_document(VALUE klass, VALUE document)

{

  xmlDocPtr doc;

  xmlRelaxNGParserCtxtPtr ctx;

  xmlRelaxNGPtr schema;

  VALUE errors;

  VALUE rb_schema;



  Data_Get_Struct(document, xmlDoc, doc);



  /* In case someone passes us a node. ugh. */

  doc = doc->doc;



  ctx = xmlRelaxNGNewDocParserCtxt(doc);



  errors = rb_ary_new();

  xmlSetStructuredErrorFunc((void *)errors, Nokogiri_error_array_pusher);



#ifdef HAVE_XMLRELAXNGSETPARSERSTRUCTUREDERRORS

  xmlRelaxNGSetParserStructuredErrors(

    ctx,

    Nokogiri_error_array_pusher,

    (void *)errors

  );

#endif



  schema = xmlRelaxNGParse(ctx);



  xmlSetStructuredErrorFunc(NULL, NULL);

  xmlRelaxNGFreeParserCtxt(ctx);



  if(NULL == schema) {

    xmlErrorPtr error = xmlGetLastError();

    if(error)

      Nokogiri_error_raise(NULL, error);

    else

      rb_raise(rb_eRuntimeError, "Could not parse document");



    return Qnil;

  }



  rb_schema = Data_Wrap_Struct(klass, 0, dealloc, schema);

  rb_iv_set(rb_schema, "@errors", errors);



  return rb_schema;

}



VALUE cNokogiriXmlRelaxNG;

void init_xml_relax_ng()

{

  VALUE nokogiri = rb_define_module("Nokogiri");

  VALUE xml = rb_define_module_under(nokogiri, "XML");

  VALUE klass = rb_define_class_under(xml, "RelaxNG", cNokogiriXmlSchema);



  cNokogiriXmlRelaxNG = klass;



  rb_define_singleton_method(klass, "read_memory", read_memory, 1);

  rb_define_singleton_method(klass, "from_document", from_document, 1);

  rb_define_private_method(klass, "validate_document", validate_document, 1);

}

