extern void _paravirt_nop(void);

asm (".pushsection .entry.text, \"ax\"\n"

     ".global _paravirt_nop\n"

     "_paravirt_nop:\n\t"

     "ret\n\t"

     ".size _paravirt_nop, . - _paravirt_nop\n\t"

     ".type _paravirt_nop, @function\n\t"

