/* gd_putout

   ** ---------

   ** Wrapper around gdPutC for use with writewbmp

   **

 */

void gd_putout (int i, void *out)

{

	gdPutC(i, (gdIOCtx *) out);

}





/* gd_getin

   ** --------

   ** Wrapper around gdGetC for use with readwbmp

   **

 */

int gd_getin (void *in)

{

	return (gdGetC((gdIOCtx *) in));

}





/*      gdImageWBMPCtx

   **  --------------

   **  Write the image as a wbmp file

   **  Parameters are:

   **  image:  gd image structure;

   **  fg:     the index of the foreground color. any other value will be

   **          considered as background and will not be written

   **  out:    the stream where to write

 */

void gdImageWBMPCtx (gdImagePtr image, int fg, gdIOCtx * out)

{

	int x, y, pos;

	Wbmp *wbmp;



	/* create the WBMP */

	if ((wbmp = createwbmp (gdImageSX (image), gdImageSY (image), WBMP_WHITE)) == NULL) {

		gd_error("Could not create WBMP");

		return;

	}



	/* fill up the WBMP structure */

	pos = 0;

	for (y = 0; y < gdImageSY(image); y++) {

		for (x = 0; x < gdImageSX(image); x++) {

			if (gdImageGetPixel (image, x, y) == fg) {

				wbmp->bitmap[pos] = WBMP_BLACK;

			}

			pos++;

		}

	}



	/* write the WBMP to a gd file descriptor */

	if (writewbmp (wbmp, &gd_putout, out)) {

		gd_error("Could not save WBMP");

	}

	/* des submitted this bugfix: gdFree the memory. */

	freewbmp(wbmp);

}



/* gdImageCreateFromWBMPCtx

   ** ------------------------

   ** Create a gdImage from a WBMP file input from an gdIOCtx

 */

gdImagePtr gdImageCreateFromWBMPCtx (gdIOCtx * infile)

{

	/* FILE *wbmp_file; */

	Wbmp *wbmp;

	gdImagePtr im = NULL;

	int black, white;

	int col, row, pos;



	if (readwbmp (&gd_getin, infile, &wbmp)) {

		return NULL;

	}



	if (!(im = gdImageCreate (wbmp->width, wbmp->height))) {

		freewbmp (wbmp);

		return NULL;

	}



	/* create the background color */

	white = gdImageColorAllocate(im, 255, 255, 255);

	/* create foreground color */

	black = gdImageColorAllocate(im, 0, 0, 0);



	/* fill in image (in a wbmp 1 = white/ 0 = black) */

	pos = 0;

	for (row = 0; row < wbmp->height; row++) {

		for (col = 0; col < wbmp->width; col++) {

			if (wbmp->bitmap[pos++] == WBMP_WHITE) {

				gdImageSetPixel(im, col, row, white);

			} else {

				gdImageSetPixel(im, col, row, black);

			}

		}

	}



	freewbmp(wbmp);



	return im;

}



/* gdImageCreateFromWBMP

   ** ---------------------

 */

gdImagePtr gdImageCreateFromWBMP (FILE * inFile)

{

	gdImagePtr im;

	gdIOCtx *in = gdNewFileCtx(inFile);

	im = gdImageCreateFromWBMPCtx(in);

	in->gd_free(in);



	return im;

}



gdImagePtr gdImageCreateFromWBMPPtr (int size, void *data)

{

	gdImagePtr im;

	gdIOCtx *in = gdNewDynamicCtxEx(size, data, 0);

	im = gdImageCreateFromWBMPCtx(in);

	in->gd_free(in);

	return im;

}



/* gdImageWBMP

   ** -----------

 */

void gdImageWBMP (gdImagePtr im, int fg, FILE * outFile)

{

	gdIOCtx *out = gdNewFileCtx(outFile);

	gdImageWBMPCtx(im, fg, out);

	out->gd_free(out);

}



/* gdImageWBMPPtr

   ** --------------

 */

void * gdImageWBMPPtr (gdImagePtr im, int *size, int fg)

{

	void *rv;

	gdIOCtx *out = gdNewDynamicCtx(2048, NULL);

	gdImageWBMPCtx(im, fg, out);

	rv = gdDPExtractData(out, size);

	out->gd_free(out);



	return rv;

}

/*

 * The Python Imaging Library.

 * $Id$

 *

 * decoder for PCX image data.

 *

 * history:

 *	95-09-14 fl	Created

 *

 * Copyright (c) Fredrik Lundh 1995.

 * Copyright (c) Secret Labs AB 1997.

 *

 * See the README file for information on usage and redistribution.

 */





#include "Imaging.h"



int

ImagingPcxDecode(Imaging im, ImagingCodecState state, UINT8* buf, Py_ssize_t bytes)

{

    UINT8 n;

    UINT8* ptr;



    if (strcmp(im->mode, "1") == 0 && state->xsize > state->bytes * 8) {

        state->errcode = IMAGING_CODEC_OVERRUN;

        return -1;

    } else if (strcmp(im->mode, "P") == 0 && state->xsize > state->bytes) {

        state->errcode = IMAGING_CODEC_OVERRUN;

        return -1;

    }



    ptr = buf;



    for (;;) {



	if (bytes < 1)

	    return ptr - buf;



	if ((*ptr & 0xC0) == 0xC0) {



	    /* Run */

	    if (bytes < 2)

		return ptr - buf;



	    n = ptr[0] & 0x3F;



	    while (n > 0) {

		if (state->x >= state->bytes) {

		    state->errcode = IMAGING_CODEC_OVERRUN;

		    break;

		}

		state->buffer[state->x++] = ptr[1];

		n--;

	    }



	    ptr += 2; bytes -= 2;



	} else {



	    /* Literal */

	    state->buffer[state->x++] = ptr[0];

	    ptr++; bytes--;



	}



	if (state->x >= state->bytes) {

        if (state->bytes % state->xsize && state->bytes > state->xsize) {

            int bands = state->bytes / state->xsize;

            int stride = state->bytes / bands;

            int i;

            for (i=1; i< bands; i++) {  // note -- skipping first band

                memmove(&state->buffer[i*state->xsize],

                        &state->buffer[i*stride],

                        state->xsize);

            }

        }

	    /* Got a full line, unpack it */

	    state->shuffle((UINT8*) im->image[state->y + state->yoff] +

			   state->xoff * im->pixelsize, state->buffer,

			   state->xsize);



	    state->x = 0;



	    if (++state->y >= state->ysize) {

		/* End of file (errcode = 0) */

		return -1;

	    }

	}



    }

}

/*

 * The Python Imaging Library.

 * $Id$

 *

 * decoder for uncompressed PCD image data.

 *

 * history:

 *	96-05-10 fl	Created

 *	96-05-18 fl	New tables

 *	97-01-25 fl	Use PhotoYCC unpacker

 *

 * notes:

 *	This driver supports uncompressed PCD modes only

 *	(resolutions up to 768x512).

 *

 * Copyright (c) Fredrik Lundh 1996-97.

 * Copyright (c) Secret Labs AB 1997.

 *

 * See the README file for information on usage and redistribution.

 */





#include "Imaging.h"





int

ImagingPcdDecode(Imaging im, ImagingCodecState state, UINT8* buf, int bytes)

{

    int x;

    int chunk;

    UINT8* out;

    UINT8* ptr;



    ptr = buf;



    chunk = 3 * state->xsize;



    for (;;) {



	/* We need data for two full lines before we can do anything */

	if (bytes < chunk)

	    return ptr - buf;



	/* Unpack first line */

	out = state->buffer;

	for (x = 0; x < state->xsize; x++) {

	    out[0] = ptr[x];

	    out[1] = ptr[(x+4*state->xsize)/2];

	    out[2] = ptr[(x+5*state->xsize)/2];

	    out += 3;

	}



	state->shuffle((UINT8*) im->image[state->y],

		       state->buffer, state->xsize);



	if (++state->y >= state->ysize)

	    return -1; /* This can hardly happen */



	/* Unpack second line */

	out = state->buffer;

	for (x = 0; x < state->xsize; x++) {

	    out[0] = ptr[x+state->xsize];

	    out[1] = ptr[(x+4*state->xsize)/2];

	    out[2] = ptr[(x+5*state->xsize)/2];

	    out += 3;

	}



	state->shuffle((UINT8*) im->image[state->y],

		       state->buffer, state->xsize);



	if (++state->y >= state->ysize)

	    return -1;



	ptr += chunk;

	bytes -= chunk;



    }

}

