    int conf_req_flag,

    gss_qop_t qop_req,

    int *conf_state,

    gss_iov_buffer_desc *iov,

    int iov_count)

{



    /* Initialize outputs. */



    if (minor_status != NULL)

	*minor_status = 0;



    /* Validate arguments. */



    if (minor_status == NULL)

	return (GSS_S_CALL_INACCESSIBLE_WRITE);



