/**

 * @file

 * QT RPZA Video Decoder by Roberto Togni

 * For more information about the RPZA format, visit:

 *   http://www.pcisys.net/~melanson/codecs/

 *

 * The RPZA decoder outputs RGB555 colorspace data.

 *

 * Note that this decoder reads big endian RGB555 pixel values from the

 * bytestream, arranges them in the host's endian order, and outputs

 * them to the final rendered map in the same host endian order. This is

 * intended behavior as the libavcodec documentation states that RGB555

 * pixels shall be stored in native CPU endianness.

 */



#include <stdio.h>

#include <stdlib.h>

#include <string.h>



#include "libavutil/internal.h"

#include "libavutil/intreadwrite.h"

#include "avcodec.h"

#include "internal.h"



typedef struct RpzaContext {



    AVCodecContext *avctx;

    AVFrame frame;



    const unsigned char *buf;

    int size;



} RpzaContext;



#define ADVANCE_BLOCK() \

{ \

    pixel_ptr += 4; \

    if (pixel_ptr >= width) \

    { \

        pixel_ptr = 0; \

        row_ptr += stride * 4; \

    } \

    total_blocks--; \

    if (total_blocks < 0) \

    { \

        av_log(s->avctx, AV_LOG_ERROR, "warning: block counter just went negative (this should not happen)\n"); \

        return; \

    } \

}



static void rpza_decode_stream(RpzaContext *s)

{

    int width = s->avctx->width;

    int stride = s->frame.linesize[0] / 2;

    int row_inc = stride - 4;

    int stream_ptr = 0;

    int chunk_size;

    unsigned char opcode;

    int n_blocks;

    unsigned short colorA = 0, colorB;

    unsigned short color4[4];

    unsigned char index, idx;

    unsigned short ta, tb;

    unsigned short *pixels = (unsigned short *)s->frame.data[0];



    int row_ptr = 0;

    int pixel_ptr = 0;

    int block_ptr;

    int pixel_x, pixel_y;

    int total_blocks;



    /* First byte is always 0xe1. Warn if it's different */

    if (s->buf[stream_ptr] != 0xe1)

        av_log(s->avctx, AV_LOG_ERROR, "First chunk byte is 0x%02x instead of 0xe1\n",

            s->buf[stream_ptr]);



    /* Get chunk size, ingnoring first byte */

    chunk_size = AV_RB32(&s->buf[stream_ptr]) & 0x00FFFFFF;

    stream_ptr += 4;



    /* If length mismatch use size from MOV file and try to decode anyway */

    if (chunk_size != s->size)

        av_log(s->avctx, AV_LOG_ERROR, "MOV chunk size != encoded chunk size; using MOV chunk size\n");



    chunk_size = s->size;



    /* Number of 4x4 blocks in frame. */

    total_blocks = ((s->avctx->width + 3) / 4) * ((s->avctx->height + 3) / 4);



    /* Process chunk data */

    while (stream_ptr < chunk_size) {

        opcode = s->buf[stream_ptr++]; /* Get opcode */



        n_blocks = (opcode & 0x1f) + 1; /* Extract block counter from opcode */



        /* If opcode MSbit is 0, we need more data to decide what to do */

        if ((opcode & 0x80) == 0) {

            colorA = (opcode << 8) | (s->buf[stream_ptr++]);

            opcode = 0;

            if ((s->buf[stream_ptr] & 0x80) != 0) {

                /* Must behave as opcode 110xxxxx, using colorA computed

                 * above. Use fake opcode 0x20 to enter switch block at

                 * the right place */

                opcode = 0x20;

                n_blocks = 1;

            }

        }



        switch (opcode & 0xe0) {



        /* Skip blocks */

        case 0x80:

            while (n_blocks--) {

              ADVANCE_BLOCK();

            }

            break;



        /* Fill blocks with one color */

        case 0xa0:

            colorA = AV_RB16 (&s->buf[stream_ptr]);

            stream_ptr += 2;

            while (n_blocks--) {

                block_ptr = row_ptr + pixel_ptr;

                for (pixel_y = 0; pixel_y < 4; pixel_y++) {

                    for (pixel_x = 0; pixel_x < 4; pixel_x++){

                        pixels[block_ptr] = colorA;

                        block_ptr++;

                    }

                    block_ptr += row_inc;

                }

                ADVANCE_BLOCK();

            }

            break;



        /* Fill blocks with 4 colors */

        case 0xc0:

            colorA = AV_RB16 (&s->buf[stream_ptr]);

            stream_ptr += 2;

        case 0x20:

            colorB = AV_RB16 (&s->buf[stream_ptr]);

            stream_ptr += 2;



            /* sort out the colors */

            color4[0] = colorB;

            color4[1] = 0;

            color4[2] = 0;

            color4[3] = colorA;



            /* red components */

            ta = (colorA >> 10) & 0x1F;

            tb = (colorB >> 10) & 0x1F;

            color4[1] |= ((11 * ta + 21 * tb) >> 5) << 10;

            color4[2] |= ((21 * ta + 11 * tb) >> 5) << 10;



            /* green components */

            ta = (colorA >> 5) & 0x1F;

            tb = (colorB >> 5) & 0x1F;

            color4[1] |= ((11 * ta + 21 * tb) >> 5) << 5;

            color4[2] |= ((21 * ta + 11 * tb) >> 5) << 5;



            /* blue components */

            ta = colorA & 0x1F;

            tb = colorB & 0x1F;

            color4[1] |= ((11 * ta + 21 * tb) >> 5);

            color4[2] |= ((21 * ta + 11 * tb) >> 5);



            if (s->size - stream_ptr < n_blocks * 4)

                return;

            while (n_blocks--) {

                block_ptr = row_ptr + pixel_ptr;

                for (pixel_y = 0; pixel_y < 4; pixel_y++) {

                    index = s->buf[stream_ptr++];

                    for (pixel_x = 0; pixel_x < 4; pixel_x++){

                        idx = (index >> (2 * (3 - pixel_x))) & 0x03;

                        pixels[block_ptr] = color4[idx];

                        block_ptr++;

                    }

                    block_ptr += row_inc;

                }

                ADVANCE_BLOCK();

            }

            break;



        /* Fill block with 16 colors */

        case 0x00:

            if (s->size - stream_ptr < 16)

                return;

            block_ptr = row_ptr + pixel_ptr;

            for (pixel_y = 0; pixel_y < 4; pixel_y++) {

                for (pixel_x = 0; pixel_x < 4; pixel_x++){

                    /* We already have color of upper left pixel */

                    if ((pixel_y != 0) || (pixel_x !=0)) {

                        colorA = AV_RB16 (&s->buf[stream_ptr]);

                        stream_ptr += 2;

                    }

                    pixels[block_ptr] = colorA;

                    block_ptr++;

                }

                block_ptr += row_inc;

            }

            ADVANCE_BLOCK();

            break;



        /* Unknown opcode */

        default:

            av_log(s->avctx, AV_LOG_ERROR, "Unknown opcode %d in rpza chunk."

                 " Skip remaining %d bytes of chunk data.\n", opcode,

                 chunk_size - stream_ptr);

            return;

        } /* Opcode switch */

    }

}



static av_cold int rpza_decode_init(AVCodecContext *avctx)

{

    RpzaContext *s = avctx->priv_data;



    s->avctx = avctx;

    avctx->pix_fmt = AV_PIX_FMT_RGB555;



    avcodec_get_frame_defaults(&s->frame);



    return 0;

}



static int rpza_decode_frame(AVCodecContext *avctx,

                             void *data, int *got_frame,

                             AVPacket *avpkt)

{

    const uint8_t *buf = avpkt->data;

    int buf_size = avpkt->size;

    RpzaContext *s = avctx->priv_data;

    int ret;



    s->buf = buf;

    s->size = buf_size;



    if ((ret = ff_reget_buffer(avctx, &s->frame)) < 0)

        return ret;



    rpza_decode_stream(s);



    if ((ret = av_frame_ref(data, &s->frame)) < 0)

        return ret;



    *got_frame      = 1;



    /* always report that the buffer was completely consumed */

    return buf_size;

}



static av_cold int rpza_decode_end(AVCodecContext *avctx)

{

    RpzaContext *s = avctx->priv_data;



    av_frame_unref(&s->frame);



    return 0;

}



AVCodec ff_rpza_decoder = {

    .name           = "rpza",

    .type           = AVMEDIA_TYPE_VIDEO,

    .id             = AV_CODEC_ID_RPZA,

    .priv_data_size = sizeof(RpzaContext),

    .init           = rpza_decode_init,

    .close          = rpza_decode_end,

    .decode         = rpza_decode_frame,

    .capabilities   = CODEC_CAP_DR1,

    .long_name      = NULL_IF_CONFIG_SMALL("QuickTime video (RPZA)"),

};

/*

** {======================================================

** Library for packing/unpacking structures.

** $Id: struct.c,v 1.7 2018/05/11 22:04:31 roberto Exp $

** See Copyright Notice at the end of this file

** =======================================================

*/

/*

** Valid formats:

** > - big endian

** < - little endian

** ![num] - alignment

** x - pading

** b/B - signed/unsigned byte

** h/H - signed/unsigned short

** l/L - signed/unsigned long

** T   - size_t

** i/In - signed/unsigned integer with size 'n' (default is size of int)

** cn - sequence of 'n' chars (from/to a string); when packing, n==0 means

        the whole string; when unpacking, n==0 means use the previous

        read number as the string length

** s - zero-terminated string

** f - float

** d - double

** ' ' - ignored

*/





#include <assert.h>

#include <ctype.h>

#include <limits.h>

#include <stddef.h>

#include <string.h>





#include "lua.h"

#include "lauxlib.h"





#if (LUA_VERSION_NUM >= 502)



#define luaL_register(L,n,f)	luaL_newlib(L,f)



#endif





/* basic integer type */

#if !defined(STRUCT_INT)

#define STRUCT_INT	long

#endif



typedef STRUCT_INT Inttype;



/* corresponding unsigned version */

typedef unsigned STRUCT_INT Uinttype;





/* maximum size (in bytes) for integral types */

#define MAXINTSIZE	32



/* is 'x' a power of 2? */

#define isp2(x)		((x) > 0 && ((x) & ((x) - 1)) == 0)



/* dummy structure to get alignment requirements */

struct cD {

  char c;

  double d;

};





#define PADDING		(sizeof(struct cD) - sizeof(double))

#define MAXALIGN  	(PADDING > sizeof(int) ? PADDING : sizeof(int))





/* endian options */

#define BIG	0

#define LITTLE	1





static union {

  int dummy;

  char endian;

} const native = {1};





typedef struct Header {

  int endian;

  int align;

} Header;





static int getnum (const char **fmt, int df) {

  if (!isdigit(**fmt))  /* no number? */

    return df;  /* return default value */

  else {

    int a = 0;

    do {

      a = a*10 + *((*fmt)++) - '0';

    } while (isdigit(**fmt));

    return a;

  }

}





#define defaultoptions(h)	((h)->endian = native.endian, (h)->align = 1)







static size_t optsize (lua_State *L, char opt, const char **fmt) {

  switch (opt) {

    case 'B': case 'b': return sizeof(char);

    case 'H': case 'h': return sizeof(short);

    case 'L': case 'l': return sizeof(long);

    case 'T': return sizeof(size_t);

    case 'f':  return sizeof(float);

    case 'd':  return sizeof(double);

    case 'x': return 1;

    case 'c': return getnum(fmt, 1);

    case 'i': case 'I': {

      int sz = getnum(fmt, sizeof(int));

      if (sz > MAXINTSIZE)

        luaL_error(L, "integral size %d is larger than limit of %d",

                       sz, MAXINTSIZE);

      return sz;

    }

    default: return 0;  /* other cases do not need alignment */

  }

}





/*

** return number of bytes needed to align an element of size 'size'

** at current position 'len'

*/

static int gettoalign (size_t len, Header *h, int opt, size_t size) {

  if (size == 0 || opt == 'c') return 0;

  if (size > (size_t)h->align)

    size = h->align;  /* respect max. alignment */

  return (size - (len & (size - 1))) & (size - 1);

}





/*

** options to control endianess and alignment

*/

static void controloptions (lua_State *L, int opt, const char **fmt,

                            Header *h) {

  switch (opt) {

    case  ' ': return;  /* ignore white spaces */

    case '>': h->endian = BIG; return;

    case '<': h->endian = LITTLE; return;

    case '!': {

      int a = getnum(fmt, MAXALIGN);

      if (!isp2(a))

        luaL_error(L, "alignment %d is not a power of 2", a);

      h->align = a;

      return;

    }

    default: {

      const char *msg = lua_pushfstring(L, "invalid format option '%c'", opt);

      luaL_argerror(L, 1, msg);

    }

  }

}





static void putinteger (lua_State *L, luaL_Buffer *b, int arg, int endian,

                        int size) {

  lua_Number n = luaL_checknumber(L, arg);

  Uinttype value;

  char buff[MAXINTSIZE];

  if (n < 0)

    value = (Uinttype)(Inttype)n;

  else

    value = (Uinttype)n;

  if (endian == LITTLE) {

    int i;

    for (i = 0; i < size; i++) {

      buff[i] = (value & 0xff);

      value >>= 8;

    }

  }

  else {

    int i;

    for (i = size - 1; i >= 0; i--) {

      buff[i] = (value & 0xff);

      value >>= 8;

    }

  }

  luaL_addlstring(b, buff, size);

}





static void correctbytes (char *b, int size, int endian) {

  if (endian != native.endian) {

    int i = 0;

    while (i < --size) {

      char temp = b[i];

      b[i++] = b[size];

      b[size] = temp;

    }

  }

}





static int b_pack (lua_State *L) {

  luaL_Buffer b;

  const char *fmt = luaL_checkstring(L, 1);

  Header h;

  int arg = 2;

  size_t totalsize = 0;

  defaultoptions(&h);

  lua_pushnil(L);  /* mark to separate arguments from string buffer */

  luaL_buffinit(L, &b);

  while (*fmt != '\0') {

    int opt = *fmt++;

    size_t size = optsize(L, opt, &fmt);

    int toalign = gettoalign(totalsize, &h, opt, size);

    totalsize += toalign;

    while (toalign-- > 0) luaL_addchar(&b, '\0');

    switch (opt) {

      case 'b': case 'B': case 'h': case 'H':

      case 'l': case 'L': case 'T': case 'i': case 'I': {  /* integer types */

        putinteger(L, &b, arg++, h.endian, size);

        break;

      }

      case 'x': {

        luaL_addchar(&b, '\0');

        break;

      }

      case 'f': {

        float f = (float)luaL_checknumber(L, arg++);

        correctbytes((char *)&f, size, h.endian);

        luaL_addlstring(&b, (char *)&f, size);

        break;

      }

      case 'd': {

        double d = luaL_checknumber(L, arg++);

        correctbytes((char *)&d, size, h.endian);

        luaL_addlstring(&b, (char *)&d, size);

        break;

      }

      case 'c': case 's': {

        size_t l;

        const char *s = luaL_checklstring(L, arg++, &l);

        if (size == 0) size = l;

        luaL_argcheck(L, l >= (size_t)size, arg, "string too short");

        luaL_addlstring(&b, s, size);

        if (opt == 's') {

          luaL_addchar(&b, '\0');  /* add zero at the end */

          size++;

        }

        break;

      }

      default: controloptions(L, opt, &fmt, &h);

    }

    totalsize += size;

  }

  luaL_pushresult(&b);

  return 1;

}





static lua_Number getinteger (const char *buff, int endian,

                        int issigned, int size) {

  Uinttype l = 0;

  int i;

  if (endian == BIG) {

    for (i = 0; i < size; i++) {

      l <<= 8;

      l |= (Uinttype)(unsigned char)buff[i];

    }

  }

  else {

    for (i = size - 1; i >= 0; i--) {

      l <<= 8;

      l |= (Uinttype)(unsigned char)buff[i];

    }

  }

  if (!issigned)

    return (lua_Number)l;

  else {  /* signed format */

    Uinttype mask = (Uinttype)(~((Uinttype)0)) << (size*8 - 1);

    if (l & mask)  /* negative value? */

      l |= mask;  /* signal extension */

    return (lua_Number)(Inttype)l;

  }

}





static int b_unpack (lua_State *L) {

  Header h;

  const char *fmt = luaL_checkstring(L, 1);

  size_t ld;

  const char *data = luaL_checklstring(L, 2, &ld);

  size_t pos = luaL_optinteger(L, 3, 1);

  luaL_argcheck(L, pos > 0, 3, "offset must be 1 or greater");

  pos--; /* Lua indexes are 1-based, but here we want 0-based for C

          * pointer math. */

  int n = 0;  /* number of results */

  defaultoptions(&h);

  while (*fmt) {

    int opt = *fmt++;

    size_t size = optsize(L, opt, &fmt);

    pos += gettoalign(pos, &h, opt, size);

    luaL_argcheck(L, size <= ld && pos <= ld - size,

                   2, "data string too short");

    /* stack space for item + next position */

    luaL_checkstack(L, 2, "too many results");

    switch (opt) {

      case 'b': case 'B': case 'h': case 'H':

      case 'l': case 'L': case 'T': case 'i':  case 'I': {  /* integer types */

        int issigned = islower(opt);

        lua_Number res = getinteger(data+pos, h.endian, issigned, size);

        lua_pushnumber(L, res); n++;

        break;

      }

      case 'x': {

        break;

      }

      case 'f': {

        float f;

        memcpy(&f, data+pos, size);

        correctbytes((char *)&f, sizeof(f), h.endian);

        lua_pushnumber(L, f); n++;

        break;

      }

      case 'd': {

        double d;

        memcpy(&d, data+pos, size);

        correctbytes((char *)&d, sizeof(d), h.endian);

        lua_pushnumber(L, d); n++;

        break;

      }

      case 'c': {

        if (size == 0) {

          if (n == 0 || !lua_isnumber(L, -1))

            luaL_error(L, "format 'c0' needs a previous size");

          size = lua_tonumber(L, -1);

          lua_pop(L, 1); n--;

          luaL_argcheck(L, size <= ld && pos <= ld - size,

                           2, "data string too short");

        }

        lua_pushlstring(L, data+pos, size); n++;

        break;

      }

      case 's': {

        const char *e = (const char *)memchr(data+pos, '\0', ld - pos);

        if (e == NULL)

          luaL_error(L, "unfinished string in data");

        size = (e - (data+pos)) + 1;

        lua_pushlstring(L, data+pos, size - 1); n++;

        break;

      }

      default: controloptions(L, opt, &fmt, &h);

    }

    pos += size;

  }

  lua_pushinteger(L, pos + 1);  /* next position */

  return n + 1;

}





static int b_size (lua_State *L) {

  Header h;

  const char *fmt = luaL_checkstring(L, 1);

  size_t pos = 0;

  defaultoptions(&h);

  while (*fmt) {

    int opt = *fmt++;

    size_t size = optsize(L, opt, &fmt);

    pos += gettoalign(pos, &h, opt, size);

    if (opt == 's')

      luaL_argerror(L, 1, "option 's' has no fixed size");

    else if (opt == 'c' && size == 0)

      luaL_argerror(L, 1, "option 'c0' has no fixed size");

    if (!isalnum(opt))

      controloptions(L, opt, &fmt, &h);

    pos += size;

  }

  lua_pushinteger(L, pos);

  return 1;

}



/* }====================================================== */







static const struct luaL_Reg thislib[] = {

  {"pack", b_pack},

  {"unpack", b_unpack},

  {"size", b_size},

  {NULL, NULL}

};





LUALIB_API int luaopen_struct (lua_State *L);



LUALIB_API int luaopen_struct (lua_State *L) {

  luaL_register(L, "struct", thislib);

  return 1;

}





