static int serdes_set_mode(struct phy *phy, enum phy_mode mode)

{

	struct serdes_macro *macro = phy_get_drvdata(phy);

	unsigned int i;

	int ret;



	for (i = 0; i < ARRAY_SIZE(ocelot_serdes_muxes); i++) {

		if (macro->idx != ocelot_serdes_muxes[i].idx ||

		    mode != ocelot_serdes_muxes[i].mode)

			continue;



		if (mode != PHY_MODE_QSGMII &&

		    macro->port != ocelot_serdes_muxes[i].port)

			continue;



		ret = regmap_update_bits(macro->ctrl->regs, HSIO_HW_CFG,

					 ocelot_serdes_muxes[i].mask,

					 ocelot_serdes_muxes[i].mux);

		if (ret)

			return ret;



		if (macro->idx <= SERDES1G_MAX)

			return serdes_init_s1g(macro->ctrl->regs, macro->idx);



		/* SERDES6G and PCIe not supported yet */

		return -EOPNOTSUPP;

	}



	return -EINVAL;

}



static const struct phy_ops serdes_ops = {

	.set_mode	= serdes_set_mode,

	.owner		= THIS_MODULE,

};



static struct phy *serdes_simple_xlate(struct device *dev,

				       struct of_phandle_args *args)

{

	struct serdes_ctrl *ctrl = dev_get_drvdata(dev);

	unsigned int port, idx, i;



	if (args->args_count != 2)

		return ERR_PTR(-EINVAL);



	port = args->args[0];

	idx = args->args[1];



	for (i = 0; i <= SERDES_MAX; i++) {

		struct serdes_macro *macro = phy_get_drvdata(ctrl->phys[i]);



		if (idx != macro->idx)

			continue;



		/* SERDES6G(0) is the only SerDes capable of QSGMII */

		if (idx != SERDES6G(0) && macro->port >= 0)

			return ERR_PTR(-EBUSY);



		macro->port = port;

		return ctrl->phys[i];

	}



	return ERR_PTR(-ENODEV);

}



static int serdes_phy_create(struct serdes_ctrl *ctrl, u8 idx, struct phy **phy)

{

	struct serdes_macro *macro;



	*phy = devm_phy_create(ctrl->dev, NULL, &serdes_ops);

	if (IS_ERR(*phy))

		return PTR_ERR(*phy);



	macro = devm_kzalloc(ctrl->dev, sizeof(*macro), GFP_KERNEL);

	if (!macro)

		return -ENOMEM;



	macro->idx = idx;

	macro->ctrl = ctrl;

	macro->port = -1;



	phy_set_drvdata(*phy, macro);



	return 0;

}



static int serdes_probe(struct platform_device *pdev)

{

	struct phy_provider *provider;

	struct serdes_ctrl *ctrl;

	unsigned int i;

	int ret;



	ctrl = devm_kzalloc(&pdev->dev, sizeof(*ctrl), GFP_KERNEL);

	if (!ctrl)

		return -ENOMEM;



	ctrl->dev = &pdev->dev;

	ctrl->regs = syscon_node_to_regmap(pdev->dev.parent->of_node);

	if (IS_ERR(ctrl->regs))

		return PTR_ERR(ctrl->regs);



	for (i = 0; i <= SERDES_MAX; i++) {

		ret = serdes_phy_create(ctrl, i, &ctrl->phys[i]);

		if (ret)

			return ret;

	}



	dev_set_drvdata(&pdev->dev, ctrl);



	provider = devm_of_phy_provider_register(ctrl->dev,

						 serdes_simple_xlate);



	return PTR_ERR_OR_ZERO(provider);

}



