flatpak_bwrap_set_env (FlatpakBwrap *bwrap,

                       const char   *variable,

                       const char   *value,

                       gboolean      overwrite)

{

  bwrap->envp = g_environ_setenv (bwrap->envp, variable, value, overwrite);

}



