/* Like popen, but gives fd instead of FILE * */

int open_pipe_fd(const char *command)

{

    int pipe_fds[2];

    int pid;

    /* "man pipe" says "filedes[0] is for reading,

     * filedes[1] is for writing. */

    if (pipe(pipe_fds) == -1)

        return -1;

    pid = fork();

    if (pid == 0) {             /* child */

        close(pipe_fds[1]);

        if (pipe_fds[0] != 0) {

            dup2(pipe_fds[0], 0);

            close(pipe_fds[0]);

        }

        execl("/bin/sh", "sh", "-c", command, (char *) 0);

        exit(EXIT_FAILURE);

    }

    close(pipe_fds[0]);

    if (pid < 0) {

        close(pipe_fds[1]);

        return -1;

    }

    return pipe_fds[1];

}



int open_net_fd(const char *spec)

{

    char *p;

    int fd, port;

    struct sockaddr_in sa;

    struct hostent *he;

    p = strchr(spec, ':');

    if (!p)

        return -1;

    *p++ = '\0';

    port = strtol(p, NULL, 10);

    /* printf("Host %s, port %d\n",spec,port); */

    sa.sin_family = PF_INET;

    sa.sin_port = htons(port);

    he = gethostbyname(spec);

    if (!he) {

#ifdef HAVE_HERROR

        herror("open_net_fd");

#endif

        return -1;

    }

    memcpy(&sa.sin_addr, he->h_addr, he->h_length);

    /* printf("using ip %s\n",inet_ntoa(sa.sin_addr)); */

    fd = socket(PF_INET, SOCK_STREAM, IPPROTO_TCP);

    if (fd < 0)

        return fd;

    if (connect(fd, (struct sockaddr *) &sa, sizeof (sa)) < 0)

        return -1;

    return fd;

}



int open_gen_fd(const char *spec)

{

    int fd;

    if (*spec == '|') {

        fd = open_pipe_fd(spec + 1);

    } else if (*spec == ':') {

        fd = open_net_fd(spec + 1);

    } else {

        fd = open(spec,

                  O_WRONLY | O_CREAT | O_APPEND,

                  S_IRUSR | S_IWUSR | S_IROTH | S_IRGRP);

    }

    return fd;

}



