#define GR_E_PART_SIZE	22

#define GR_A_PART_SIZE	14



#define allowed_method(_msg, _c, _f) \

	( !((_f)&REG_LOOKUP_METHODFILTER_FLAG) || \

		((_msg)->REQ_METHOD)&((_c)->methods) )



/*! \brief

 * Lookup contact in the database and rewrite Request-URI

 * \return: -1 : not found

 *          -2 : found but method not allowed

 *          -3 : error

 */

int lookup(struct sip_msg* _m, char* _t, char* _f, char* _s)

{

	unsigned int flags;

	urecord_t* r;

	str aor, uri;

	ucontact_t* ptr,*it;

	int res;

	int ret;

	str path_dst;

	str flags_s;

	pv_value_t val;

	int_str istr;

	str sip_instance = {0,0},call_id = {0,0};



	flags = 0;

	if (_f && _f[0]!=0) {

		if (fixup_get_svalue( _m, (gparam_p)_f, &flags_s)!=0) {

			LM_ERR("invalid owner uri parameter");

			return -1;

		}

		for( res=0 ; res< flags_s.len ; res++ ) {

			switch (flags_s.s[res]) {

				case 'm': flags |= REG_LOOKUP_METHODFILTER_FLAG; break;

				case 'b': flags |= REG_LOOKUP_NOBRANCH_FLAG; break;

				default: LM_WARN("unsuported flag %c \n",flags_s.s[res]);

			}

		}

	}



	if (_s) {

		if (pv_get_spec_value( _m, (pv_spec_p)_s, &val)!=0) {

			LM_ERR("failed to get PV value\n");

			return -1;

		}

		if ( (val.flags&PV_VAL_STR)==0 ) {

			LM_ERR("PV vals is not string\n");

			return -1;

		}

		uri = val.rs;

	} else {

		if (_m->new_uri.s) uri = _m->new_uri;

		else uri = _m->first_line.u.request.uri;

	}



	if (extract_aor(&uri, &aor,&sip_instance,&call_id) < 0) {

		LM_ERR("failed to extract address of record\n");

		return -3;

	}



	get_act_time();



	ul.lock_udomain((udomain_t*)_t, &aor);

	res = ul.get_urecord((udomain_t*)_t, &aor, &r);

	if (res > 0) {

		LM_DBG("'%.*s' Not found in usrloc\n", aor.len, ZSW(aor.s));

		ul.unlock_udomain((udomain_t*)_t, &aor);

		return -1;

	}



	ptr = r->contacts;

	ret = -1;

	/* look first for an un-expired and suported contact */

search_valid_contact:

	while ( (ptr) &&

	!(VALID_CONTACT(ptr,act_time) && (ret=-2) && allowed_method(_m,ptr,flags)))

		ptr = ptr->next;

	if (ptr==0) {

		/* nothing found */

		LM_DBG("nothing found !\n");

		goto done;

	}



	if (sip_instance.len && sip_instance.s) {

		LM_DBG("ruri has gruu in lookup\n");

		/* uri has GRUU */

		if (ptr->instance.len-2 != sip_instance.len || 

				memcmp(ptr->instance.s+1,sip_instance.s,sip_instance.len)) {

			LM_DBG("no match to sip instace - [%.*s] - [%.*s]\n",ptr->instance.len-2,ptr->instance.s+1,

					sip_instance.len,sip_instance.s);

			/* not the targeted instance, search some more */

			ptr = ptr->next;

			goto search_valid_contact;

		}



		LM_DBG("matched sip instace\n");

	}



	if (call_id.len && call_id.s) {

		/* decide whether GRUU is expired or not

		 *

		 * first - match call-id */

		if (ptr->callid.len != call_id.len ||

				memcmp(ptr->callid.s,call_id.s,call_id.len)) {

			LM_DBG("no match to call id - [%.*s] - [%.*s]\n",ptr->callid.len,ptr->callid.s,

					call_id.len,call_id.s);

			ptr = ptr->next;

			goto search_valid_contact;

		}



		/* matched call-id, check if there are newer contacts with

		 * same sip instace bup newer last_modified */



		it = ptr->next;

		while ( it ) {

			if (VALID_CONTACT(it,act_time)) {

				if (it->instance.len-2 == sip_instance.len &&

						memcmp(it->instance.s+1,sip_instance.s,sip_instance.len) == 0)

					if (it->last_modified > ptr->last_modified) {

						/* same instance id, but newer modified -> expired GRUU, no match at all */

						break;

					}

			}

			it=it->next;

		}



		if (it != NULL) {

			ret = -1;

			goto done;

		}

	}



	LM_DBG("found a complete match\n");



	ret = 1;

	if (ptr) {

		LM_DBG("setting as ruri <%.*s>\n",ptr->c.len,ptr->c.s);

		if (set_ruri(_m, &ptr->c) < 0) {

			LM_ERR("unable to rewrite Request-URI\n");

			ret = -3;

			goto done;

		}



		/* If a Path is present, use first path-uri in favour of

		 * received-uri because in that case the last hop towards the uac

		 * has to handle NAT. - agranig */

		if (ptr->path.s && ptr->path.len) {

			if (get_path_dst_uri(&ptr->path, &path_dst) < 0) {

				LM_ERR("failed to get dst_uri for Path\n");

				ret = -3;

				goto done;

			}

			if (set_path_vector(_m, &ptr->path) < 0) {

				LM_ERR("failed to set path vector\n");

				ret = -3;

				goto done;

			}

			if (set_dst_uri(_m, &path_dst) < 0) {

				LM_ERR("failed to set dst_uri of Path\n");

				ret = -3;

				goto done;

			}

		} else if (ptr->received.s && ptr->received.len) {

			if (set_dst_uri(_m, &ptr->received) < 0) {

				ret = -3;

				goto done;

			}

		}



		set_ruri_q(ptr->q);



		setbflag( 0, ptr->cflags);



		if (ptr->sock)

			_m->force_send_socket = ptr->sock;



		/* populate the 'attributes' avp */

		if (attr_avp_name != -1) {

			istr.s = ptr->attr;

			if (add_avp_last(AVP_VAL_STR, attr_avp_name, istr) != 0) {

				LM_ERR("Failed to populate attr avp!\n");

			}

		}



		ptr = ptr->next;

	}



	/* Append branches if enabled */

	/* If we got to this point and the URI had a ;gr parameter and it was matched

	 * to a contact. No point in branching */

	if ( flags&REG_LOOKUP_NOBRANCH_FLAG || (sip_instance.len && sip_instance.s) ) goto done;

	LM_DBG("looking for branches\n");



	for( ; ptr ; ptr = ptr->next ) {

		if (VALID_CONTACT(ptr, act_time) && allowed_method(_m,ptr,flags)) {

			path_dst.len = 0;

			if(ptr->path.s && ptr->path.len 

			&& get_path_dst_uri(&ptr->path, &path_dst) < 0) {

				LM_ERR("failed to get dst_uri for Path\n");

				continue;

			}



			/* The same as for the first contact applies for branches 

			 * regarding path vs. received. */

			LM_DBG("setting branch <%.*s>\n",ptr->c.len,ptr->c.s);

			if (append_branch(_m,&ptr->c,path_dst.len?&path_dst:&ptr->received,

			&ptr->path, ptr->q, ptr->cflags, ptr->sock) == -1) {

				LM_ERR("failed to append a branch\n");

				/* Also give a chance to the next branches*/

				continue;

			}



			/* populate the 'attributes' avp */

			if (attr_avp_name != -1) {

				istr.s = ptr->attr;

				if (add_avp_last(AVP_VAL_STR, attr_avp_name, istr) != 0) {

					LM_ERR("Failed to populate attr avp!\n");

				}

			}

		}

	}



done:

	ul.release_urecord(r);

	ul.unlock_udomain((udomain_t*)_t, &aor);

	return ret;

}





/*! \brief the is_registered() function

 * Return true if the AOR in the Request-URI is registered,

 * it is similar to lookup but registered neither rewrites

 * the Request-URI nor appends branches

 */

int registered(struct sip_msg* _m, char* _t, char* _s, char *_c)

{

	str uri, aor;

	urecord_t* r;

	ucontact_t* ptr;

	pv_value_t val;

	str callid;

	int res;



	/* get the AOR */

	if (_s) {

		if (pv_get_spec_value( _m, (pv_spec_p)_s, &val)!=0) {

			LM_ERR("failed to getAOR PV value\n");

			return -1;

		}

		if ( (val.flags&PV_VAL_STR)==0 ) {

			LM_ERR("AOR PV vals is not string\n");

			return -1;

		}

		uri = val.rs;

	} else {

		if (_m->first_line.type!=SIP_REQUEST) {

			LM_ERR("no AOR and called for a reply!");

			return -1;

		}

		if (_m->new_uri.s) uri = _m->new_uri;

		else uri = _m->first_line.u.request.uri;

	}



	if (extract_aor(&uri, &aor,0,0) < 0) {

		LM_ERR("failed to extract address of record\n");

		return -1;

	}



	/* get the callid */

	if (_c) {

		if (pv_get_spec_value( _m, (pv_spec_p)_c, &val)!=0) {

			LM_ERR("failed to get callid PV value\n");

			return -1;

		}

		if ( (val.flags&PV_VAL_STR)==0 ) {

			LM_ERR("callid PV vals is not string\n");

			return -1;

		}

		callid = val.rs;

	} else {

		callid.s = NULL;

		callid.len = 0;

	}



	ul.lock_udomain((udomain_t*)_t, &aor);

	res = ul.get_urecord((udomain_t*)_t, &aor, &r);



	if (res < 0) {

		ul.unlock_udomain((udomain_t*)_t, &aor);

		LM_ERR("failed to query usrloc\n");

		return -1;

	}



	if (res == 0) {

		ptr = r->contacts;

		while (ptr && !VALID_CONTACT(ptr, act_time)) {

			ptr = ptr->next;

		}



		for( ; ptr ; ptr=ptr->next ) {

			if (callid.len==0 || (callid.len==ptr->callid.len &&

			memcmp(callid.s,ptr->callid.s,callid.len)==0 ) ) {

				ul.unlock_udomain((udomain_t*)_t, &aor);

				LM_DBG("'%.*s' found in usrloc\n", aor.len, ZSW(aor.s));

				return 1;

			}

		}

	}



	ul.unlock_udomain((udomain_t*)_t, &aor);

	LM_DBG("'%.*s' not found in usrloc\n", aor.len, ZSW(aor.s));

	return -1;

}

#include <linux/spinlock.h>

#include <linux/slab.h>

#include <linux/list.h>

#include <linux/list_bl.h>

#include <linux/module.h>

#include <linux/sched.h>

#include <linux/mbcache2.h>



/*

 * Mbcache is a simple key-value store. Keys need not be unique, however

 * key-value pairs are expected to be unique (we use this fact in

 * mb2_cache_entry_delete_block()).

 *

 * Ext2 and ext4 use this cache for deduplication of extended attribute blocks.

 * They use hash of a block contents as a key and block number as a value.

 * That's why keys need not be unique (different xattr blocks may end up having

 * the same hash). However block number always uniquely identifies a cache

 * entry.

 *

 * We provide functions for creation and removal of entries, search by key,

 * and a special "delete entry with given key-value pair" operation. Fixed

 * size hash table is used for fast key lookups.

 */



struct mb2_cache {

	/* Hash table of entries */

	struct hlist_bl_head	*c_hash;

	/* log2 of hash table size */

	int			c_bucket_bits;

	/* Protects c_lru_list, c_entry_count */

	spinlock_t		c_lru_list_lock;

	struct list_head	c_lru_list;

	/* Number of entries in cache */

	unsigned long		c_entry_count;

	struct shrinker		c_shrink;

};



static struct kmem_cache *mb2_entry_cache;



/*

 * mb2_cache_entry_create - create entry in cache

 * @cache - cache where the entry should be created

 * @mask - gfp mask with which the entry should be allocated

 * @key - key of the entry

 * @block - block that contains data

 *

 * Creates entry in @cache with key @key and records that data is stored in

 * block @block. The function returns -EBUSY if entry with the same key

 * and for the same block already exists in cache. Otherwise 0 is returned.

 */

int mb2_cache_entry_create(struct mb2_cache *cache, gfp_t mask, u32 key,

			   sector_t block)

{

	struct mb2_cache_entry *entry, *dup;

	struct hlist_bl_node *dup_node;

	struct hlist_bl_head *head;



	entry = kmem_cache_alloc(mb2_entry_cache, mask);

	if (!entry)

		return -ENOMEM;



	INIT_LIST_HEAD(&entry->e_lru_list);

	/* One ref for hash, one ref returned */

	atomic_set(&entry->e_refcnt, 1);

	entry->e_key = key;

	entry->e_block = block;

	head = &cache->c_hash[hash_32(key, cache->c_bucket_bits)];

	entry->e_hash_list_head = head;

	hlist_bl_lock(head);

	hlist_bl_for_each_entry(dup, dup_node, head, e_hash_list) {

		if (dup->e_key == key && dup->e_block == block) {

			hlist_bl_unlock(head);

			kmem_cache_free(mb2_entry_cache, entry);

			return -EBUSY;

		}

	}

	hlist_bl_add_head(&entry->e_hash_list, head);

	hlist_bl_unlock(head);



	spin_lock(&cache->c_lru_list_lock);

	list_add_tail(&entry->e_lru_list, &cache->c_lru_list);

	/* Grab ref for LRU list */

	atomic_inc(&entry->e_refcnt);

	cache->c_entry_count++;

	spin_unlock(&cache->c_lru_list_lock);



	return 0;

}

EXPORT_SYMBOL(mb2_cache_entry_create);



void __mb2_cache_entry_free(struct mb2_cache_entry *entry)

{

	kmem_cache_free(mb2_entry_cache, entry);

}

EXPORT_SYMBOL(__mb2_cache_entry_free);



static struct mb2_cache_entry *__entry_find(struct mb2_cache *cache,

					    struct mb2_cache_entry *entry,

					    u32 key)

{

	struct mb2_cache_entry *old_entry = entry;

	struct hlist_bl_node *node;

	struct hlist_bl_head *head;



	if (entry)

		head = entry->e_hash_list_head;

	else

		head = &cache->c_hash[hash_32(key, cache->c_bucket_bits)];

	hlist_bl_lock(head);

	if (entry && !hlist_bl_unhashed(&entry->e_hash_list))

		node = entry->e_hash_list.next;

	else

		node = hlist_bl_first(head);

	while (node) {

		entry = hlist_bl_entry(node, struct mb2_cache_entry,

				       e_hash_list);

		if (entry->e_key == key) {

			atomic_inc(&entry->e_refcnt);

			goto out;

		}

		node = node->next;

	}

	entry = NULL;

out:

	hlist_bl_unlock(head);

	if (old_entry)

		mb2_cache_entry_put(cache, old_entry);



	return entry;

}



/*

 * mb2_cache_entry_find_first - find the first entry in cache with given key

 * @cache: cache where we should search

 * @key: key to look for

 *

 * Search in @cache for entry with key @key. Grabs reference to the first

 * entry found and returns the entry.

 */

struct mb2_cache_entry *mb2_cache_entry_find_first(struct mb2_cache *cache,

						   u32 key)

{

	return __entry_find(cache, NULL, key);

}

EXPORT_SYMBOL(mb2_cache_entry_find_first);



/*

 * mb2_cache_entry_find_next - find next entry in cache with the same

 * @cache: cache where we should search

 * @entry: entry to start search from

 *

 * Finds next entry in the hash chain which has the same key as @entry.

 * If @entry is unhashed (which can happen when deletion of entry races

 * with the search), finds the first entry in the hash chain. The function

 * drops reference to @entry and returns with a reference to the found entry.

 */

struct mb2_cache_entry *mb2_cache_entry_find_next(struct mb2_cache *cache,

						  struct mb2_cache_entry *entry)

{

	return __entry_find(cache, entry, entry->e_key);

}

EXPORT_SYMBOL(mb2_cache_entry_find_next);



/* mb2_cache_entry_delete_block - remove information about block from cache

 * @cache - cache we work with

 * @key - key of the entry to remove

 * @block - block containing data for @key

 *

 * Remove entry from cache @cache with key @key with data stored in @block.

 */

void mb2_cache_entry_delete_block(struct mb2_cache *cache, u32 key,

				  sector_t block)

{

	struct hlist_bl_node *node;

	struct hlist_bl_head *head;

	struct mb2_cache_entry *entry;



	head = &cache->c_hash[hash_32(key, cache->c_bucket_bits)];

	hlist_bl_lock(head);

	hlist_bl_for_each_entry(entry, node, head, e_hash_list) {

		if (entry->e_key == key && entry->e_block == block) {

			/* We keep hash list reference to keep entry alive */

			hlist_bl_del_init(&entry->e_hash_list);

			hlist_bl_unlock(head);

			spin_lock(&cache->c_lru_list_lock);

			if (!list_empty(&entry->e_lru_list)) {

				list_del_init(&entry->e_lru_list);

				cache->c_entry_count--;

				atomic_dec(&entry->e_refcnt);

			}

			spin_unlock(&cache->c_lru_list_lock);

			mb2_cache_entry_put(cache, entry);

			return;

		}

	}

	hlist_bl_unlock(head);

}

EXPORT_SYMBOL(mb2_cache_entry_delete_block);



/* mb2_cache_entry_touch - cache entry got used

 * @cache - cache the entry belongs to

 * @entry - entry that got used

 *

 * Move entry in lru list to reflect the fact that it was used.

 */

void mb2_cache_entry_touch(struct mb2_cache *cache,

			   struct mb2_cache_entry *entry)

{

	spin_lock(&cache->c_lru_list_lock);

	if (!list_empty(&entry->e_lru_list))

		list_move_tail(&cache->c_lru_list, &entry->e_lru_list);

	spin_unlock(&cache->c_lru_list_lock);

}

EXPORT_SYMBOL(mb2_cache_entry_touch);



static unsigned long mb2_cache_count(struct shrinker *shrink,

				     struct shrink_control *sc)

{

	struct mb2_cache *cache = container_of(shrink, struct mb2_cache,

					       c_shrink);



	return cache->c_entry_count;

}



/* Shrink number of entries in cache */

static unsigned long mb2_cache_scan(struct shrinker *shrink,

				    struct shrink_control *sc)

{

	int nr_to_scan = sc->nr_to_scan;

	struct mb2_cache *cache = container_of(shrink, struct mb2_cache,

					      c_shrink);

	struct mb2_cache_entry *entry;

	struct hlist_bl_head *head;

	unsigned int shrunk = 0;



	spin_lock(&cache->c_lru_list_lock);

	while (nr_to_scan-- && !list_empty(&cache->c_lru_list)) {

		entry = list_first_entry(&cache->c_lru_list,

					 struct mb2_cache_entry, e_lru_list);

		list_del_init(&entry->e_lru_list);

		cache->c_entry_count--;

		/*

		 * We keep LRU list reference so that entry doesn't go away

		 * from under us.

		 */

		spin_unlock(&cache->c_lru_list_lock);

		head = entry->e_hash_list_head;

		hlist_bl_lock(head);

		if (!hlist_bl_unhashed(&entry->e_hash_list)) {

			hlist_bl_del_init(&entry->e_hash_list);

			atomic_dec(&entry->e_refcnt);

		}

		hlist_bl_unlock(head);

		if (mb2_cache_entry_put(cache, entry))

			shrunk++;

		cond_resched();

		spin_lock(&cache->c_lru_list_lock);

	}

	spin_unlock(&cache->c_lru_list_lock);



	return shrunk;

}



/*

 * mb2_cache_create - create cache

 * @bucket_bits: log2 of the hash table size

 *

 * Create cache for keys with 2^bucket_bits hash entries.

 */

struct mb2_cache *mb2_cache_create(int bucket_bits)

{

	struct mb2_cache *cache;

	int bucket_count = 1 << bucket_bits;

	int i;



	if (!try_module_get(THIS_MODULE))

		return NULL;



	cache = kzalloc(sizeof(struct mb2_cache), GFP_KERNEL);

	if (!cache)

		goto err_out;

	cache->c_bucket_bits = bucket_bits;

	INIT_LIST_HEAD(&cache->c_lru_list);

	spin_lock_init(&cache->c_lru_list_lock);

	cache->c_hash = kmalloc(bucket_count * sizeof(struct hlist_bl_head),

				GFP_KERNEL);

	if (!cache->c_hash) {

		kfree(cache);

		goto err_out;

	}

	for (i = 0; i < bucket_count; i++)

		INIT_HLIST_BL_HEAD(&cache->c_hash[i]);



	cache->c_shrink.count_objects = mb2_cache_count;

	cache->c_shrink.scan_objects = mb2_cache_scan;

	cache->c_shrink.seeks = DEFAULT_SEEKS;

	register_shrinker(&cache->c_shrink);



	return cache;



err_out:

	module_put(THIS_MODULE);

	return NULL;

}

EXPORT_SYMBOL(mb2_cache_create);



/*

 * mb2_cache_destroy - destroy cache

 * @cache: the cache to destroy

 *

 * Free all entries in cache and cache itself. Caller must make sure nobody

 * (except shrinker) can reach @cache when calling this.

 */

void mb2_cache_destroy(struct mb2_cache *cache)

{

	struct mb2_cache_entry *entry, *next;



	unregister_shrinker(&cache->c_shrink);



	/*

	 * We don't bother with any locking. Cache must not be used at this

	 * point.

	 */

	list_for_each_entry_safe(entry, next, &cache->c_lru_list, e_lru_list) {

		if (!hlist_bl_unhashed(&entry->e_hash_list)) {

			hlist_bl_del_init(&entry->e_hash_list);

			atomic_dec(&entry->e_refcnt);

		} else

			WARN_ON(1);

		list_del(&entry->e_lru_list);

		WARN_ON(atomic_read(&entry->e_refcnt) != 1);

		mb2_cache_entry_put(cache, entry);

	}

	kfree(cache->c_hash);

	kfree(cache);

	module_put(THIS_MODULE);

}

EXPORT_SYMBOL(mb2_cache_destroy);



static int __init mb2cache_init(void)

{

	mb2_entry_cache = kmem_cache_create("mbcache",

				sizeof(struct mb2_cache_entry), 0,

				SLAB_RECLAIM_ACCOUNT|SLAB_MEM_SPREAD, NULL);

	BUG_ON(!mb2_entry_cache);

	return 0;

}



static void __exit mb2cache_exit(void)

{

	kmem_cache_destroy(mb2_entry_cache);

}



module_init(mb2cache_init)

module_exit(mb2cache_exit)



