#include "edge_proxy_common.h"



void edge_sparse_csr_reader_double( const char*           i_csr_file_in,

                                    unsigned int**        o_row_idx,

                                    unsigned int**        o_column_idx,

                                    double**              o_values,

                                    unsigned int*         o_row_count,

                                    unsigned int*         o_column_count,

                                    unsigned int*         o_element_count ) {

  FILE *l_csr_file_handle;

  const unsigned int l_line_length = 512;

  char l_line[512/*l_line_length*/+1];

  unsigned int l_header_read = 0;

  unsigned int* l_row_idx_id = NULL;

  unsigned int l_i = 0;



  l_csr_file_handle = fopen( i_csr_file_in, "r" );

  if ( l_csr_file_handle == NULL ) {

    fprintf( stderr, "cannot open CSR file!\n" );

    return;

  }



  while (fgets(l_line, l_line_length, l_csr_file_handle) != NULL) {

    if ( strlen(l_line) == l_line_length ) {

      fprintf( stderr, "could not read file length!\n" );

      return;

    }

    /* check if we are still reading comments header */

    if ( l_line[0] == '%' ) {

      continue;

    } else {

      /* if we are the first line after comment header, we allocate our data structures */

      if ( l_header_read == 0 ) {

        if ( sscanf(l_line, "%u %u %u", o_row_count, o_column_count, o_element_count) == 3 ) {

          /* allocate CSC datastructure matching mtx file */

          *o_column_idx = (unsigned int*) malloc(sizeof(unsigned int) * (*o_element_count));

          *o_row_idx = (unsigned int*) malloc(sizeof(unsigned int) * (*o_row_count + 1));

          *o_values = (double*) malloc(sizeof(double) * (*o_element_count));

          l_row_idx_id = (unsigned int*) malloc(sizeof(unsigned int) * (*o_row_count));



          /* check if mallocs were successful */

          if ( ( *o_row_idx == NULL )      ||

               ( *o_column_idx == NULL )   ||

               ( *o_values == NULL )       ||

               ( l_row_idx_id == NULL ) ) {

            fprintf( stderr, "could not allocate sp data!\n" );

            return;

          }



          /* set everything to zero for init */

          memset(*o_row_idx, 0, sizeof(unsigned int)*(*o_row_count + 1));

          memset(*o_column_idx, 0, sizeof(unsigned int)*(*o_element_count));

          memset(*o_values, 0, sizeof(double)*(*o_element_count));

          memset(l_row_idx_id, 0, sizeof(unsigned int)*(*o_row_count));



          /* init column idx */

          for ( l_i = 0; l_i < (*o_row_count + 1); l_i++)

            (*o_row_idx)[l_i] = (*o_element_count);



          /* init */

          (*o_row_idx)[0] = 0;

          l_i = 0;

          l_header_read = 1;

        } else {

          fprintf( stderr, "could not csr description!\n" );

          return;

        }

      /* now we read the actual content */

      } else {

        unsigned int l_row, l_column;

        double l_value;

        /* read a line of content */

        if ( sscanf(l_line, "%u %u %lf", &l_row, &l_column, &l_value) != 3 ) {

          fprintf( stderr, "could not read element!\n" );

          return;

        }

        /* adjust numbers to zero termination */

        l_row--;

        l_column--;

        /* add these values to row and value structure */

        (*o_column_idx)[l_i] = l_column;

        (*o_values)[l_i] = l_value;

        l_i++;

        /* handle columns, set id to own for this column, yeah we need to handle empty columns */

        l_row_idx_id[l_row] = 1;

        (*o_row_idx)[l_row+1] = l_i;

      }

    }

  }



  /* close mtx file */

  fclose( l_csr_file_handle );



  /* check if we read a file which was consistent */

  if ( l_i != (*o_element_count) ) {

    fprintf( stderr, "we were not able to read all elements!\n" );

    return;

  }



  /* let's handle empty rows */

  for ( l_i = 0; l_i < (*o_row_count); l_i++) {

    if ( l_row_idx_id[l_i] == 0 ) {

      (*o_row_idx)[l_i+1] = (*o_row_idx)[l_i];

    }

  }



  /* free helper data structure */

  if ( l_row_idx_id != NULL ) {

    free( l_row_idx_id );

  }

}



void edge_sparse_csr_reader_float( const char*           i_csr_file_in,

                                   unsigned int**        o_row_idx,

                                   unsigned int**        o_column_idx,

                                   float**               o_values,

                                   unsigned int*         o_row_count,

                                   unsigned int*         o_column_count,

                                   unsigned int*         o_element_count ) {

  double* l_values;

  unsigned int i;



  /* read using double */

  edge_sparse_csr_reader_double( i_csr_file_in, o_row_idx, o_column_idx, &l_values,

                                   o_row_count, o_column_count, o_element_count );



  /* converting double values into float */

  *o_values = (float*) malloc((*o_element_count)*sizeof(float));

  for ( i = 0; i < (*o_element_count); ++i ) {

    (*o_values)[i] = (float)l_values[i];

  }



  free(l_values);

}

/*

 * Glue code for libmspack handling.

 * Author: 웃 Sebastian Andrzej Siewior

 * ✉ sebastian @ breakpoint ̣cc

 */



#include <stdio.h>

#include <stdlib.h>

#include <sys/stat.h>

#include <fcntl.h>



#include <mspack.h>



#include "clamav.h"

#include "fmap.h"

#include "scanners.h"

#include "others.h"



enum mspack_type {

	FILETYPE_DUNNO,

	FILETYPE_FMAP,

	FILETYPE_FILENAME,

};



struct mspack_name {

	fmap_t *fmap;

	off_t org;

};



struct mspack_system_ex {

	struct mspack_system ops;

	off_t max_size;

};



struct mspack_handle {

	enum mspack_type type;



	fmap_t *fmap;

	off_t org;

	off_t offset;



	FILE *f;

	off_t max_size;

};



static struct mspack_file *mspack_fmap_open(struct mspack_system *self,

		const char *filename, int mode)

{

	struct mspack_name *mspack_name;

	struct mspack_handle *mspack_handle;

	struct mspack_system_ex *self_ex;

	const char *fmode;

        const struct mspack_system *mptr = self;



	if (!filename) {

		cli_dbgmsg("%s() failed at %d\n", __func__, __LINE__);

		return NULL;

	}

	mspack_handle = malloc(sizeof(*mspack_handle));

	if (!mspack_handle) {

		cli_dbgmsg("%s() failed at %d\n", __func__, __LINE__);

		return NULL;

	}

	switch (mode) {

	case MSPACK_SYS_OPEN_READ:

		mspack_handle->type = FILETYPE_FMAP;



		mspack_name = (struct mspack_name *)filename;

		mspack_handle->fmap = mspack_name->fmap;

		mspack_handle->org = mspack_name->org;

		mspack_handle->offset = 0;



		return (struct mspack_file *)mspack_handle;



	case MSPACK_SYS_OPEN_WRITE:

		fmode = "wb";

		break;

	case MSPACK_SYS_OPEN_UPDATE:

		fmode = "r+b";

		break;

	case MSPACK_SYS_OPEN_APPEND:

		fmode = "ab";

		break;

	default:

		cli_dbgmsg("%s() wrong mode\n", __func__);

		goto out_err;

	}



	mspack_handle->type = FILETYPE_FILENAME;



	mspack_handle->f = fopen(filename, fmode);

	if (!mspack_handle->f) {

		cli_dbgmsg("%s() failed %d\n", __func__, __LINE__);

		goto out_err;

	}



	self_ex = (struct mspack_system_ex *)((char *)mptr - offsetof(struct mspack_system_ex,ops));

	mspack_handle->max_size = self_ex->max_size;

	return (struct mspack_file *)mspack_handle;



out_err:

	free(mspack_handle);

	return NULL;

}



static void mspack_fmap_close(struct mspack_file *file)

{

	struct mspack_handle *mspack_handle = (struct mspack_handle *)file;



	if (!mspack_handle)

		return;



	if (mspack_handle->type == FILETYPE_FILENAME)

		fclose(mspack_handle->f);

	free(mspack_handle);

}



static int mspack_fmap_read(struct mspack_file *file, void *buffer, int bytes)

{

	struct mspack_handle *mspack_handle = (struct mspack_handle *)file;

	off_t offset;

	size_t count;

	int ret;



	if (bytes < 0) {

		cli_dbgmsg("%s() %d\n", __func__, __LINE__);

		return -1;

	}

	if (!mspack_handle) {

		cli_dbgmsg("%s() %d\n", __func__, __LINE__);

		return -1;

	}



	if (mspack_handle->type == FILETYPE_FMAP) {

		offset = mspack_handle->offset + mspack_handle->org;



		ret = fmap_readn(mspack_handle->fmap, buffer, offset, bytes);

		if (ret != bytes) {

			cli_dbgmsg("%s() %d %d, %d\n", __func__, __LINE__, bytes, ret);

			return ret;

		}



		mspack_handle->offset += bytes;

		return bytes;

	}

	count = fread(buffer, bytes, 1, mspack_handle->f);

	if (count < 1) {

		cli_dbgmsg("%s() %d %d, %zd\n", __func__, __LINE__, bytes, count);

		return -1;

	}

	return bytes;

}



static int mspack_fmap_write(struct mspack_file *file, void *buffer, int bytes)

{

	struct mspack_handle *mspack_handle = (struct mspack_handle *)file;

	size_t count;

	off_t max_size;



	if (bytes < 0 || !mspack_handle) {

		cli_dbgmsg("%s() err %d\n", __func__, __LINE__);

		return -1;

	}



	if (mspack_handle->type == FILETYPE_FMAP) {

		cli_dbgmsg("%s() err %d\n", __func__, __LINE__);

		return -1;

	}



	if (!bytes)

		return 0;



	max_size = mspack_handle->max_size;

	if (!max_size)

		return bytes;



	max_size = max_size < (off_t) bytes ? max_size : (off_t) bytes;



	mspack_handle->max_size -= max_size;



	count = fwrite(buffer, max_size, 1, mspack_handle->f);

	if (count < 1) {

		cli_dbgmsg("%s() err %m <%zd %d>\n", __func__, count, bytes);

		return -1;

	}



	return bytes;

}



static int mspack_fmap_seek(struct mspack_file *file, off_t offset, int mode)

{

	struct mspack_handle *mspack_handle = (struct mspack_handle *)file;



	if (!mspack_handle) {

		cli_dbgmsg("%s() err %d\n", __func__, __LINE__);

		return -1;

	}



	if (mspack_handle->type == FILETYPE_FMAP) {

		off_t new_pos;



		switch (mode) {

		case MSPACK_SYS_SEEK_START:

			new_pos = offset;

			break;

		case MSPACK_SYS_SEEK_CUR:

			new_pos = mspack_handle->offset + offset;

			break;

		case MSPACK_SYS_SEEK_END:

			new_pos = mspack_handle->fmap->len + offset;

			break;

		default:

			cli_dbgmsg("%s() err %d\n", __func__, __LINE__);

			return -1;

		}

		if (new_pos < 0 || new_pos > mspack_handle->fmap->len) {

			cli_dbgmsg("%s() err %d\n", __func__, __LINE__);

			return -1;

		}



		mspack_handle->offset = new_pos;

		return 0;

	}



	switch (mode) {

	case MSPACK_SYS_SEEK_START:

		mode = SEEK_SET;

		break;

	case MSPACK_SYS_SEEK_CUR:

		mode = SEEK_CUR;

		break;

	case MSPACK_SYS_SEEK_END:

		mode = SEEK_END;

		break;

	default:

		cli_dbgmsg("%s() err %d\n", __func__, __LINE__);

		return -1;

	}



	return fseek(mspack_handle->f, offset, mode);

}



static off_t mspack_fmap_tell(struct mspack_file *file)

{

	struct mspack_handle *mspack_handle = (struct mspack_handle *)file;



	if (!mspack_handle)

		return -1;



	if (mspack_handle->type == FILETYPE_FMAP)

		return mspack_handle->offset;



	return (off_t) ftell(mspack_handle->f);

}



static void mspack_fmap_message(struct mspack_file *file, const char *fmt, ...)

{

	cli_dbgmsg("%s() %s\n", __func__, fmt);

}

static void *mspack_fmap_alloc(struct mspack_system *self, size_t num)

{

	return malloc(num);

}



static void mspack_fmap_free(void *mem)

{

    if(mem) {

        free(mem);

        mem = NULL;

    }

    return;

}



static void mspack_fmap_copy(void *src, void *dst, size_t num)

{

	memcpy(dst, src, num);

}



static struct mspack_system mspack_sys_fmap_ops = {

	.open = mspack_fmap_open,

	.close = mspack_fmap_close,

	.read = mspack_fmap_read,

	.write = mspack_fmap_write,

	.seek = mspack_fmap_seek,

	.tell = mspack_fmap_tell,

	.message = mspack_fmap_message,

	.alloc = mspack_fmap_alloc,

	.free = mspack_fmap_free,

	.copy = mspack_fmap_copy,

};



static int cli_scanfile(const char *filename, cli_ctx *ctx)

{

	int fd, ret;



	/* internal version of cl_scanfile with arec/mrec preserved */

	fd = safe_open(filename, O_RDONLY|O_BINARY);

	if (fd < 0)

		return CL_EOPEN;



	ret = cli_magic_scandesc(fd, ctx);



	close(fd);

	return ret;

}



int cli_scanmscab(cli_ctx *ctx, off_t sfx_offset)

{

	struct mscab_decompressor *cab_d;

	struct mscabd_cabinet *cab_h;

	struct mscabd_file *cab_f;

	int ret;

	int files;

	int virus_num = 0;

	struct mspack_name mspack_fmap = {

		.fmap	= *ctx->fmap,

		.org	= sfx_offset,

	};

	struct mspack_system_ex ops_ex;

	memset(&ops_ex, 0, sizeof(struct mspack_system_ex));

 	ops_ex.ops = mspack_sys_fmap_ops;



	MSPACK_SYS_SELFTEST(ret);

	if (ret) {

		cli_dbgmsg("%s() failed at %d\n", __func__, __LINE__);

		return CL_EUNPACK;

	}



	cab_d = mspack_create_cab_decompressor(&ops_ex.ops);

	if (!cab_d) {

		cli_dbgmsg("%s() failed at %d\n", __func__, __LINE__);

		return CL_EUNPACK;

	}



	cab_h = cab_d->open(cab_d, (char *)&mspack_fmap);

	if (!cab_h) {

		ret = CL_EFORMAT;

		cli_dbgmsg("%s() failed at %d\n", __func__, __LINE__);

		goto out_dest;

	}

	files = 0;

	for (cab_f = cab_h->files; cab_f; cab_f = cab_f->next) {

		off_t max_size;

		char *tmp_fname;



		ret = cli_matchmeta(ctx, cab_f->filename, 0, cab_f->length, 0,

				files, 0, NULL);

		if (ret) {

			if (ret == CL_VIRUS) {

				virus_num++;

				if (!SCAN_ALL)

					break;

			}

			goto out_close;

		}



		if (ctx->engine->maxscansize) {

			if (ctx->scansize >= ctx->engine->maxscansize) {

				ret = CL_CLEAN;

				break;

			}

		}



		if (ctx->engine->maxscansize &&

				ctx->scansize + ctx->engine->maxfilesize >=

				ctx->engine->maxscansize)

			max_size = ctx->engine->maxscansize -

				ctx->scansize;

		else

			max_size = ctx->engine->maxfilesize ?

				ctx->engine->maxfilesize :

				0xffffffff;



		tmp_fname = cli_gentemp(ctx->engine->tmpdir);

		if (!tmp_fname) {

			ret = CL_EMEM;

			break;

		}



		ops_ex.max_size = max_size;

		/* scan */

		ret = cab_d->extract(cab_d, cab_f, tmp_fname);

		if (ret)

			/* Failed to extract. Try to scan what is there */

			cli_dbgmsg("%s() failed to extract %d\n", __func__, ret);



		ret = cli_scanfile(tmp_fname, ctx);

		if (ret == CL_VIRUS)

			virus_num++;



		if (!ctx->engine->keeptmp) {

			if (!access(tmp_fname, R_OK) && cli_unlink(tmp_fname)) {

				free(tmp_fname);

				ret = CL_EUNLINK;

				break;

			}

		}

		free(tmp_fname);

		files++;

		if (ret == CL_VIRUS && SCAN_ALL)

			continue;

		if (ret)

			break;

	}



out_close:

	cab_d->close(cab_d, cab_h);

out_dest:

	mspack_destroy_cab_decompressor(cab_d);

	if (virus_num)

		return CL_VIRUS;

	return ret;

}



