	fd = open(dev, O_RDWR);

	if (fd < 0) {

		printf("Failed to open %s with errno %s\n", dev,

		       strerror(errno));

		return EXIT_FAILURE;



	}

	thread_func(start, start + gap, fd);



	sleep(1000000);

	return EXIT_FAILURE;

}

